export function A1_QUESTIONS(){return[
  {type:'mc',era:'Colonial',q:'In what year was Jamestown founded?',correct:'1607',wrong:['1585','1620','1630'],explain:'The Virginia Company landed at Jamestown on May 14, 1607 — thirteen years before the Pilgrims reached Plymouth.'},
  {type:'mc',era:'Colonial',q:'Which body formally established the Church of England in Virginia in 1619?',correct:'The House of Burgesses',wrong:['The Virginia Company','The Privy Council','The Bishop of London'],explain:'The House of Burgesses, convening for the first time in 1619, established Anglicanism as Virginia\'s official religion, backed by a tobacco tax.'},
  {type:'mc',era:'Colonial',q:'Why was the absence of a bishop the Church of England\'s greatest structural weakness in Virginia?',correct:'Ordination, confirmation, and discipline all required a bishop — making them effectively unavailable locally',wrong:['The king had forbidden bishops in the colonies until 1700','Bishops collected all parish taxes and sent them to England','Virginia law barred bishops from entering the colony'],explain:'Without a bishop, Virginia-born candidates for ordination had to sail to England. Confirmation was simply unavailable, and unfit clergy could rarely be effectively disciplined.'},
  {type:'mc',era:'Colonial',q:'What was the name of the lay board that governed Anglican parishes in Virginia?',correct:'The vestry',wrong:['The presbytery','The consistory','The synod'],explain:'Virginia vestries — boards of prominent planters — held far more power than their English equivalents because no bishop was present to oversee parish life.'},
  {type:'mc',era:'Colonial',q:'Which minister baptized Pocahontas in 1613?',correct:'Alexander Whitaker',wrong:['Robert Hunt','James Blair','Richard Buck'],explain:'Whitaker, known as "the Apostle of Virginia," baptized Pocahontas at Henrico. She took the name Rebecca and married John Rolfe the following year.'},
  {type:'tf',era:'Colonial',q:'Virginia established the Church of England before the Pilgrims arrived in New England.',answer:true,explain:'The House of Burgesses established Anglicanism in Virginia in 1619 — one year before the Mayflower reached Plymouth in 1620.'},
  {type:'tf',era:'Colonial',q:'The Church of England in Virginia was governed by a bishop who lived in Williamsburg.',answer:false,explain:'There was no bishop anywhere in the American colonies during the colonial period. The Bishop of London held nominal oversight but could exercise little practical authority across the Atlantic.'},
  {type:'mc',era:'Colonial',q:'Which English colony was the first to establish the Church of England as its official church?',correct:'Virginia',wrong:['Massachusetts Bay','Plymouth','Maryland'],explain:'Anglican worship arrived at Jamestown in 1607, and Virginia\'s House of Burgesses formally established the Church of England in 1619. New England colonies were Puritan/Congregationalist.'},
  {type:'quote',era:'Colonial',quote:'"What should I say to you in this place of summer?"',cite:'— Good Newes from Virginia, 1613',q:'Who wrote this letter urging England to send missionaries to Virginia?',correct:'Alexander Whitaker',wrong:['Robert Hunt','John Rolfe','George Percy'],explain:'Whitaker, called the "Apostle of Virginia," wrote enthusiastically from Henrico about the colony\'s prospects and the spiritual opportunity it represented.'},
  {type:'mc',era:'Colonial',q:'Which came first?',correct:'Jamestown was founded and Rev. Robert Hunt led the first Anglican worship in Virginia',wrong:['The House of Burgesses formally established the Church of England as Virginia\'s official religion'],explain:'Jamestown was founded in 1607 — twelve years before the House of Burgesses established Anglicanism as Virginia\'s official religion in 1619.'},
  {type:'mc',era:'Colonial',q:'On what cape did the first Jamestown colonists plant a cross in 1607?',correct:'Cape Henry',wrong:['Cape Cod','Cape Fear','Cape Charles','Cape May','Cape Hatteras','Cape Ann'],explain:'The 1607 colonists planted a cross at Cape Henry and erected a sail-cloth chapel on the shore.'},
  {type:'mc',era:'Colonial',q:'At which settlement did Alexander Whitaker baptize Pocahontas?',correct:'Henrico',wrong:['Jamestown','Williamsburg','Norfolk','Richmond','Yorktown','Cape Henry'],explain:'Whitaker, the "Apostle of Virginia," baptized Pocahontas at Henrico in 1613.'},
  {type:'mc',era:'Colonial',q:'What Christian name did Pocahontas take at her baptism?',correct:'Rebecca',wrong:['Mary','Rachel','Ruth','Sarah','Martha','Hannah'],explain:'Pocahontas took the name Rebecca at her baptism and married John Rolfe the following year.'},
  {type:'mc',era:'Colonial',q:'Whom did Pocahontas marry the year after her baptism?',correct:'John Rolfe',wrong:['John Smith','Alexander Whitaker','Robert Hunt','Thomas Dale','William Bradford','George Percy'],explain:'Pocahontas married the planter John Rolfe in 1614, a year after her baptism at Henrico.'},
  {type:'mc',era:'Colonial',q:'Until what year could Catholics not legally worship openly in Virginia?',correct:'1781',wrong:['1607','1619','1649','1700','1776','1791'],explain:'The Anglican establishment was so dominant that Catholics could not legally worship openly in Virginia until 1781.'},
]}

export function A2_QUESTIONS(){return[
  {type:'mc',era:'Colonial',q:'What distinguished the Plymouth Pilgrims from the later Massachusetts Bay Puritans?',correct:'The Pilgrims were Separatists who had broken entirely from the Church of England; the Massachusetts Bay Puritans hoped to reform it from within',wrong:['The Pilgrims were Anglicans; the Massachusetts Bay settlers were Presbyterians','The Pilgrims came for economic reasons; the Massachusetts Bay settlers were purely religious','The Pilgrims were Catholic; the Massachusetts Bay settlers were Protestant'],explain:'The Plymouth founders had separated entirely from the Church of England and worshiped in Leiden, Holland, before sailing. The 1630 Massachusetts Bay settlers remained technically within the Church of England while seeking to purify it.'},
  {type:'mc',era:'Colonial',q:'John Winthrop\'s "city upon a hill" image came from which book of the Bible?',correct:'Matthew (the Sermon on the Mount)',wrong:['Isaiah','Psalms','Revelation'],explain:'Matthew 5:14 reads, "You are the light of the world. A city set on a hill cannot be hidden." Winthrop used this verse to argue that the Puritan colony\'s success or failure would be visible to the watching world.'},
  {type:'mc',era:'Colonial',q:'What was required to become a full member of a Massachusetts Bay church?',correct:'A public "relation" — an account of one\'s conversion experience before the congregation',wrong:['Completion of a two-year catechism course','Payment of the church tax','Approval by the colonial governor'],explain:'Massachusetts Congregationalists required aspiring members to give a credible account of conversion before the gathered congregation. Those admitted became "visible saints" — full members with voting rights.'},
  {type:'mc',era:'Colonial',q:'What form of church governance did the Massachusetts Bay churches use?',correct:'Congregationalism — each local church self-governing, with no bishop or synod above it',wrong:['Episcopalianism — governed by bishops appointed by the king','Presbyterianism — governed by regional presbyteries','Erastianism — governed directly by the civil government'],explain:'Massachusetts churches were Congregationalist: each gathered church was autonomous. There was no bishop to appoint ministers or discipline members. The Cambridge Platform (1648) later codified this system.'},
  {type:'mc',era:'Colonial',q:'Harvard College was founded in 1636 primarily for what purpose?',correct:'To train a literate ministry for the colony\'s churches',wrong:['To educate the children of Native peoples','To teach navigation and merchant skills','To train lawyers and magistrates for the colonial government'],explain:'The 1643 pamphlet New England\'s First Fruits stated the founders dreaded "to leave an illiterate ministry to the churches when our present ministers shall lie in the dust."'},
  {type:'tf',era:'Colonial',q:'The Mayflower Compact established universal male suffrage in Plymouth Colony.',answer:false,explain:'The Compact bound 41 adult male signers into a "civil body politic" for the common good, but it excluded women, servants, and non-signers. It was a step toward consent-based government, not full democracy.'},
  {type:'tf',era:'Colonial',q:'Massachusetts Bay Colony was founded by Quakers fleeing Anglican persecution.',answer:false,explain:'Massachusetts Bay was founded by Calvinist Puritan non-Separatists. Quakers who later entered the colony were whipped and jailed; four were hanged on Boston Common between 1659 and 1661.'},
  {type:'tf',era:'Colonial',q:'Winthrop\'s "city upon a hill" sermon framed the Massachusetts venture as a covenant with God.',answer:true,explain:'Winthrop argued that Massachusetts had entered a formal covenant with God, meaning its success would honor God and its failure would bring judgment — and that all the world would observe the outcome.'},
  {type:'quote',era:'Colonial',quote:'"For we must consider that we shall be as a city upon a hill. The eyes of all people are upon us."',cite:'— John Winthrop, "A Model of Christian Charity," c. 1630',q:'What is the key claim Winthrop makes with this image?',correct:'That the Massachusetts colony is a covenanted community whose success or failure will be visible to God and the watching world',wrong:['That Massachusetts will become the capital of a new Christian empire','That God has guaranteed the colony\'s military success','That New Englanders are spiritually superior to other colonists'],explain:'Winthrop drew from Matthew 5:14 to frame Massachusetts as a covenant before God — one whose failure would shame God\'s cause before all nations.'},
  {type:'mc',era:'Colonial',q:'Which came first?',correct:'The Pilgrims signed the Mayflower Compact and Plymouth Colony was founded',wrong:['John Winthrop led the Great Migration to Massachusetts Bay'],explain:'The Plymouth Pilgrims arrived in 1620 — a decade before Winthrop\'s 1630 Great Migration. The Pilgrims were Separatists; Winthrop\'s group were non-Separatist Puritans who hoped to reform the Church of England from within.'},
  {type:'mc',era:'Colonial',q:'Which document bound the 1620 Mayflower passengers into a "civil body politic"?',correct:'The Mayflower Compact',wrong:['The Plymouth Charter','The Pilgrim Covenant','The Bradford Articles'],explain:'Signed by 41 adult male passengers on November 11, 1620, the Mayflower Compact was the first self-governing document drafted by English settlers in North America.'},
  {type:'mc',era:'Colonial',q:'Who led the 1630 Puritan migration to Massachusetts Bay and preached the "city upon a hill" sermon?',correct:'John Winthrop',wrong:['William Bradford','John Cotton','Roger Williams'],explain:'Winthrop, first governor of Massachusetts Bay, is credited with "A Model of Christian Charity," framing the colony as a divine covenant watched by the whole world.'},
  {type:'mc',era:'Colonial',q:'Aboard which ship did John Winthrop preach "A Model of Christian Charity"?',correct:'The Arbella',wrong:['The Mayflower','The Speedwell','The Susan Constant','The Godspeed','The Welcome','The Discovery'],explain:'Winthrop preached the founding sermon aboard the Arbella as the Great Migration fleet crossed in 1630.'},
  {type:'mc',era:'Colonial',q:'About how many settlers did Winthrop lead to Massachusetts Bay in 1630?',correct:'About 700',wrong:['About 100','About 41','About 1,500','About 2,000','About 5,000','About 300'],explain:'Winthrop led roughly 700 settlers and 11 ships to Massachusetts Bay in 1630.'},
  {type:'mc',era:'Colonial',q:'Where did the Pilgrims land in 1620 after missing Virginia?',correct:'Cape Cod',wrong:['Cape Henry','Jamestown','Boston','Salem','Cape Ann','Cape May'],explain:'The Mayflower missed Virginia and landed at Cape Cod, where the Pilgrims signed the Mayflower Compact.'},
  {type:'mc',era:'Colonial',q:'In which Dutch city had the Separatist Pilgrims lived before sailing for America?',correct:'Leiden',wrong:['Amsterdam','Rotterdam','The Hague','Delft','Haarlem','Utrecht'],explain:'The Separatist congregation had fled England for Leiden, Holland, before sailing on the Mayflower in 1620.'},
  {type:'mc',era:'Colonial',q:'What 1648 document codified the Congregational church system in Massachusetts?',correct:'The Cambridge Platform',wrong:['The Half-Way Covenant','The Mayflower Compact','The Westminster Confession','The Saybrook Platform','The Bay Psalm Book','The Cambridge Agreement'],explain:'The Cambridge Platform (1648) codified the self-governing Congregational polity of the Massachusetts churches.'},
]}

export function A3_QUESTIONS(){return[
  {type:'mc',era:'Colonial',q:'For what reason was Roger Williams banished from Massachusetts Bay in 1636?',correct:'Spreading dangerous opinions, including that civil magistrates had no authority over religious conscience',wrong:['Denying the divinity of Christ','Refusing to pay the church tax','Teaching that infants should not be baptized'],explain:'The Massachusetts General Court convicted Williams of sedition and heresy. He argued the civil government had no power over conscience and that the king\'s charter could not grant Indian land without purchase.'},
  {type:'mc',era:'Colonial',q:'What colony did Roger Williams found in 1636?',correct:'Providence (Rhode Island)',wrong:['New Haven','Connecticut','Maryland'],explain:'After his banishment, Williams settled on land purchased from the Narragansett and called the settlement Providence. Rhode Island became the first government in the English-speaking world to guarantee religious liberty.'},
  {type:'mc',era:'Colonial',q:'What was the central theological charge Anne Hutchinson leveled at most Massachusetts ministers?',correct:'That they preached a "covenant of works" rather than a "covenant of grace"',wrong:['That they rejected believer\'s baptism','That they secretly held Catholic views','That they had abandoned Calvinist predestination'],explain:'Hutchinson accused most ministers (excepting John Cotton) of teaching salvation by moral effort rather than free grace. The dispute — the Antinomian Controversy — tore the colony apart in 1636–1638.'},
  {type:'mc',era:'Colonial',q:'What 1649 Maryland law granted free exercise of religion to all Trinitarian Christians?',correct:'The Act Concerning Religion (Toleration Act)',wrong:['The Frame of Government','The Maryland Charter of Privileges','The Calvert Compact'],explain:'Passed April 21, 1649, the Act was the first religious toleration law in the English colonies. It protected Trinitarian Christians but sentenced to death anyone who denied the doctrine of the Trinity.'},
  {type:'mc',era:'Colonial',q:'William Penn founded Pennsylvania in 1681 as what kind of colony?',correct:'A "holy experiment" of religious liberty open to all peaceable believers',wrong:['An Anglican colony loyal to the king','A strictly Quaker theocracy','A refuge exclusively for persecuted Catholics'],explain:'Penn, a wealthy English Quaker, used a royal land grant to establish a colony that welcomed Quakers, Mennonites, German Pietists, Jews, and others. Pennsylvania became the most religiously plural of all the colonies.'},
  {type:'tf',era:'Colonial',q:'Roger Williams helped found the first Baptist church in America.',answer:true,explain:'Williams helped organize the first Baptist congregation in Providence around 1638, after being persuaded of believers\' baptism. He left it shortly after, concluding that no true visible church yet existed before Christ\'s return.'},
  {type:'tf',era:'Colonial',q:'The Maryland Toleration Act of 1649 extended religious freedom to all people regardless of religion.',answer:false,explain:'The Act protected only Trinitarian Christians. It explicitly sentenced to death anyone who denied the divinity of Jesus and excluded Jews, Unitarians, and non-Christians from its protections.'},
  {type:'mc',era:'Colonial',q:'Roger Williams\'s 1644 defense of religious liberty was titled The Bloudy Tenent of what?',correct:'Persecution',wrong:['Oppression','Tyranny','Conformity'],explain:'Williams published The Bloudy Tenent of Persecution in London in 1644, arguing that forced religion produced only hypocrites and bloodshed — and that the state had no jurisdiction over the soul.'},
  {type:'mc',era:'Colonial',q:'Maryland was originally founded by Cecil Calvert partly as a refuge for which persecuted group?',correct:'English Catholics',wrong:['Quakers','Puritans','Baptists'],explain:'The Calverts were an English Catholic family. Though Protestants soon outnumbered Catholics in Maryland, the 1649 Toleration Act reflected the proprietors\' interest in protecting Catholic worship.'},
  {type:'quote',era:'Colonial',quote:'"It is the will and command of God that a permission of the most paganish, Jewish, Turkish, or anti-Christian consciences and worships, be granted to all men."',cite:'— Roger Williams, The Bloudy Tenent of Persecution, 1644',q:'What principle was Williams defending with this statement?',correct:'Liberty of conscience — the freedom of individual religious belief from civil interference',wrong:['Universal salvation for all religions','The right of Massachusetts to banish dissenters','Quaker principles of inner light'],explain:'Williams argued that forced religion was contrary to Scripture and produced only hypocrisy and bloodshed — a position far ahead of his time in the English-speaking world.'},
  {type:'mc',era:'Colonial',q:'Which came first?',correct:'Roger Williams was banished from Massachusetts and founded Providence',wrong:['William Penn founded Pennsylvania as a "holy experiment" of religious liberty'],explain:'Williams founded Providence after his 1636 banishment — forty-five years before Penn\'s 1681 colony. Williams planted the first seeds of religious liberty in the English colonies; Penn built the most fully realized experiment in pluralism.'},
  {type:'mc',era:'Colonial',q:'Which Native people sheltered Roger Williams after his banishment?',correct:'The Narragansett',wrong:['The Wampanoag','The Pequot','The Mohegan','The Powhatan','The Iroquois','The Lenape'],explain:'Williams fled south and was sheltered by the Narragansett, on whose land he founded Providence.'},
  {type:'mc',era:'Colonial',q:'The dispute over Anne Hutchinson is known by what name?',correct:'The Antinomian Controversy',wrong:['The Half-Way Covenant','The Great Awakening','The Salem panic','The Pequot War','The Cambridge Synod','The Toleration Controversy'],explain:'Hutchinson\'s 1636–1638 conflict with the Massachusetts ministers is called the Antinomian Controversy.'},
  {type:'mc',era:'Colonial',q:'Who founded Maryland in 1634 as a refuge for English Catholics?',correct:'Cecil Calvert',wrong:['William Penn','Lord De La Warr','John Smith','James Oglethorpe','William Bradford','Thomas Hooker'],explain:'Cecil Calvert, an English Catholic proprietor, founded Maryland in 1634; it passed the Act Concerning Religion in 1649.'},
  {type:'mc',era:'Colonial',q:'In what year did William Penn found Pennsylvania?',correct:'1681',wrong:['1634','1636','1649','1620','1607','1701'],explain:'William Penn founded Pennsylvania in 1681 as a "holy experiment" in religious liberty.'},
  {type:'mc',era:'Colonial',q:'Besides Mennonites, Huguenots, and Jews, Penn\'s Pennsylvania welcomed German what?',correct:'Pietists',wrong:['Lutherans','Catholics','Calvinists','Anabaptists','Moravians','Baptists'],explain:'Penn welcomed Mennonites, German Pietists, Huguenots, and Jews — making Pennsylvania the most religiously plural colony.'},
]}

export function A4_QUESTIONS(){return[
  {type:'mc',era:'Colonial',q:'What problem did the Half-Way Covenant of 1662 attempt to solve?',correct:'Declining church membership as the children of founding Puritans failed to report conversion experiences',wrong:['A dispute between Congregationalists and Presbyterians over baptism','The refusal of English immigrants to join colonial churches','A theological debate over predestination and free will'],explain:'As the first-generation "visible saints" aged and died, their children and grandchildren often could not give the conversion narratives required for full membership. The Half-Way Covenant extended baptism — but not the Lord\'s Supper — to the children of partial members.'},
  {type:'mc',era:'Colonial',q:'What did the Half-Way Covenant allow that had previously been restricted?',correct:'Baptism for the children of baptized but unconverted parents',wrong:['Women to vote in church elections','Non-Christians to attend church services','Civil magistrates to administer baptism'],explain:'The 1662 synod voted to baptize the children of members who had been baptized as infants but never professed conversion. Critics saw this as compromising the ideal of a church of the truly converted.'},
  {type:'mc',era:'Colonial',q:'What type of evidence did Salem courts accept that critics said made the trials a travesty?',correct:'Spectral evidence — testimony about visions or dreams of the accused',wrong:['Confessions obtained under torture','Hearsay from neighbors with known grudges','Evidence gathered by searching for physical marks on the accused'],explain:'Spectral evidence — testimony that the accused\'s spirit had appeared in a dream or vision — was impossible to disprove. Its admission made Salem convictions nearly inevitable, and its rejection ended the trials.'},
  {type:'mc',era:'Colonial',q:'How many people were executed as a result of the Salem witch trials?',correct:'Twenty — nineteen by hanging and one (Giles Corey) pressed to death',wrong:['Five, all by drowning','None — all were ultimately pardoned','Over fifty, mostly burned at the stake'],explain:'Nineteen accused witches were hanged on Gallows Hill between June and September 1692. Giles Corey, who refused to enter a plea, was pressed to death with heavy stones. More than 150 were accused in total; five others died in jail.'},
  {type:'mc',era:'Colonial',q:'Which Salem trial judge later made a public confession of guilt for his role in the proceedings?',correct:'Samuel Sewall',wrong:['William Stoughton','John Hathorne','Increase Mather'],explain:'On Fast Day in January 1697, Samuel Sewall stood in Boston\'s Old South Church while a confession of his guilt was read aloud. He was the only Salem trial judge to publicly repent.'},
  {type:'tf',era:'Colonial',q:'The Half-Way Covenant gave partial-member children full access to the Lord\'s Supper.',answer:false,explain:'The Half-Way Covenant extended baptism to the children of unconverted members, but it explicitly did not grant access to the Lord\'s Supper or a vote in church affairs. Full membership still required a profession of faith.'},
  {type:'tf',era:'Colonial',q:'Governor Phips ended the Salem trials after Increase Mather and other ministers raised concerns about spectral evidence.',answer:true,explain:'After ministers including Increase Mather wrote against spectral evidence in late 1692, Phips dissolved the Court of Oyer and Terminer in October 1692 and forbade its use. Remaining accused were largely acquitted or released.'},
  {type:'mc',era:'Colonial',q:'During the Salem trials, which father-and-son pair took opposing stances on the prosecutions?',correct:'Cotton Mather (defended prosecutions) and Increase Mather (argued against spectral evidence)',wrong:['Increase Mather (defended) and Cotton Mather (argued against)','Samuel Sewall and John Hale','John Cotton and Richard Mather'],explain:'Cotton Mather wrote Wonders of the Invisible World (1692) defending the prosecutions. His father Increase Mather wrote Cases of Conscience (1692) arguing against spectral evidence — helping persuade Phips to dissolve the court.'},
  {type:'quote',era:'Colonial',quote:'"They knew they were pilgrims, and looked not much on those things, but lifted up their eyes to the heavens, their dearest country."',cite:'— William Bradford, Of Plymouth Plantation, c. 1650',q:'What lesson is Bradford drawing from the Pilgrim experience?',correct:'That the saints\' ultimate identity is heavenly — they hold earthly things loosely as travelers passing through',wrong:['That the Pilgrims had failed in their mission to build a Christian society','That Bradford regretted the decision to sail to America','That the Pilgrims were homesick for England'],explain:'Bradford\'s phrase "they were pilgrims" gave the Plymouth founders their enduring name. He was reflecting on how those who live by faith hold the world loosely, their eyes lifted to a heavenly country.'},
  {type:'mc',era:'Colonial',q:'Which came first?',correct:'The Half-Way Covenant was adopted, extending baptism to the children of unconverted members',wrong:['The Salem witch trials resulted in nineteen hangings and shattered Puritan authority'],explain:'The Half-Way Covenant was adopted in 1662 — thirty years before the Salem witch trials of 1692. Together they mark the arc of Puritan decline: first a compromise on membership, then a judicial catastrophe.'},
  {type:'mc',era:'Colonial',q:'The Massachusetts magistrate who publicly repented for his role in the Salem trials was Judge Samuel _____.',correct:'Sewall',wrong:['Hathorne','Stoughton','Corwin'],explain:'On Fast Day in January 1697, Samuel Sewall stood in Boston\'s Old South Church while a public confession of his Salem-trial guilt was read aloud. He was the only Salem judge to repent publicly.'},
  {type:'mc',era:'Colonial',q:'What 1676 war devastated New England and was read as God\'s judgment?',correct:"King Philip's War",wrong:['The Pequot War','The French and Indian War','Bacon\'s Rebellion','Queen Anne\'s War','The Yamasee War','The Antinomian War'],explain:'King Philip\'s War (1676) killed thousands and razed dozens of towns; ministers called it judgment on a backsliding people.'},
  {type:'mc',era:'Colonial',q:'On what hill were the nineteen condemned of Salem hanged?',correct:'Gallows Hill',wrong:['Beacon Hill','Bunker Hill','Copp\'s Hill','Breed\'s Hill','Cotton Hill','Witch Hill'],explain:'Nineteen accused were hanged on Gallows Hill in 1692; Giles Corey was pressed to death.'},
  {type:'mc',era:'Colonial',q:'In which 1692 work did Cotton Mather defend the Salem prosecutions?',correct:'Wonders of the Invisible World',wrong:['Cases of Conscience','Magnalia Christi Americana','The Bloudy Tenent','Seasonable Thoughts','A Faithful Narrative','Of Plymouth Plantation'],explain:'Cotton Mather defended the prosecutions in Wonders of the Invisible World (1692).'},
  {type:'mc',era:'Colonial',q:'In which 1692 work did Increase Mather argue against spectral evidence?',correct:'Cases of Conscience',wrong:['Wonders of the Invisible World','Magnalia Christi Americana','Seasonable Thoughts','The Bloudy Tenent','A Faithful Narrative','Of Plymouth Plantation'],explain:'Increase Mather\'s Cases of Conscience (1692) argued against spectral evidence, helping end the trials.'},
  {type:'mc',era:'Colonial',q:'In which Boston church was Judge Sewall\'s confession read aloud in 1697?',correct:'Old South Church',wrong:['First Church','Old North Church','King\'s Chapel','Park Street Church','Trinity Church','Third Church'],explain:'In 1697 Samuel Sewall stood in Boston\'s Old South Church while his public confession of guilt was read.'},
]}

export function A5_QUESTIONS(){return[
  {type:'mc',era:'First Awakening',q:'What denomination did Theodorus Frelinghuysen belong to?',correct:'Dutch Reformed',wrong:['Anglican','Presbyterian','Baptist'],explain:'Frelinghuysen was a Dutch Reformed pietist who ministered in the Raritan Valley of New Jersey beginning in 1720. His urgent preaching of personal conversion influenced Gilbert Tennent and is often called the first stirring of the First Great Awakening.'},
  {type:'mc',era:'First Awakening',q:'What did Frelinghuysen controversially require as a prerequisite for receiving communion?',correct:'Evidence of genuine personal conversion',wrong:['A two-year catechism course','Payment of church dues','Approval from the Dutch classis in Amsterdam'],explain:'Frelinghuysen insisted that only those who had genuinely experienced God\'s saving grace should receive the Lord\'s Supper. This demand created conflict in his denomination but also produced genuine revival.'},
  {type:'mc',era:'First Awakening',q:'What was the "Log College" and why was it significant?',correct:'A small school on William Tennent\'s Pennsylvania farm that trained revivalist Presbyterian ministers',wrong:['A Sunday school program for frontier children','A nickname for Harvard given by its Puritan opponents','A colonial college founded by the Dutch Reformed'],explain:'William Tennent\'s log-cabin school trained his sons and others in evangelical Reformed theology. Its graduates — including Gilbert Tennent — became leaders of the New Side Presbyterian revival movement and a direct precursor to Princeton.'},
  {type:'mc',era:'First Awakening',q:'Where did Jonathan Edwards serve as minister when the 1734–35 revival occurred?',correct:'Northampton, Massachusetts',wrong:['New Haven','Providence','Boston'],explain:'Edwards had followed his grandfather Solomon Stoddard as pastor of Northampton\'s Congregational church. The sudden town-wide awakening of 1734–35 was his first experience of large-scale revival.'},
  {type:'mc',era:'First Awakening',q:'What was the significance of Edwards\'s A Faithful Narrative of the Surprising Work of God (1737)?',correct:'It gave the Atlantic evangelical world a model account of revival, preparing leaders to recognize a similar work of the Spirit in the colonies',wrong:['It was the founding document of the New Side Presbyterian movement','It was the first American book to sell over a thousand copies','It convinced George Whitefield to come to America'],explain:'Edwards\'s Faithful Narrative circulated widely in Britain and the colonies, read by figures including John Wesley and George Whitefield. It established a vocabulary and template for understanding revival that shaped everything that followed.'},
  {type:'tf',era:'First Awakening',q:'Theodorus Frelinghuysen was a Congregationalist minister from New England.',answer:false,explain:'Frelinghuysen was a Dutch Reformed pietist from continental Europe who ministered in the Raritan Valley of New Jersey beginning in 1720.'},
  {type:'tf',era:'First Awakening',q:'Jonathan Edwards\'s Northampton revival preceded George Whitefield\'s arrival in the colonies.',answer:true,explain:'The Northampton awakening of 1734–35 and Edwards\'s account of it (1737) came before Whitefield\'s transformative American preaching tours beginning in 1739–1740.'},
  {type:'mc',era:'First Awakening',q:'Which Dutch Reformed pietist minister in New Jersey is often called the first stirring of the Great Awakening in the Middle Colonies?',correct:'Theodorus Frelinghuysen',wrong:['Gilbert Tennent','William Tennent','George Whitefield'],explain:'Frelinghuysen\'s pietist preaching in the Raritan Valley of New Jersey beginning in the 1720s influenced Gilbert Tennent and is often identified as the earliest precursor of the Great Awakening in America.'},
  {type:'quote',era:'First Awakening',quote:'"There was scarcely a single person in the town, either old or young, that was left unconcerned about the great things of the eternal world."',cite:'— Jonathan Edwards, A Faithful Narrative, 1737',q:'What event was Edwards describing?',correct:'The sudden revival awakening in Northampton, Massachusetts in 1734–35',wrong:['The Salem witch trials of 1692','The aftermath of King Philip\'s War','Whitefield\'s 1740 preaching tour'],explain:'Edwards\'s Faithful Narrative described a Northampton revival that touched nearly every person in the town — a claim that stunned readers on both sides of the Atlantic and prepared them for more.'},
  {type:'mc',era:'First Awakening',q:'Which came first?',correct:'Frelinghuysen arrived in New Jersey and began revival preaching in the Raritan Valley',wrong:['Jonathan Edwards reported surprising conversions in Northampton, Massachusetts'],explain:'Frelinghuysen began preaching around 1720 — fourteen years before Edwards\'s Northampton revival of 1734–35. Frelinghuysen\'s example shaped Gilbert Tennent and is often called the first stirring of the Awakening.'},
  {type:'mc',era:'First Awakening',q:'Edwards\'s 1737 published account of the Northampton revival was titled A Faithful Narrative of the Surprising Work of what?',correct:'God',wrong:['the Spirit','Christ','Revival'],explain:'A Faithful Narrative of the Surprising Work of God (1737) circulated widely in Britain and America, helping leaders recognize the scattered local revivals as a single transatlantic movement.'},
  {type:'mc',era:'First Awakening',q:'In which New Jersey valley did Frelinghuysen preach revival?',correct:'The Raritan Valley',wrong:['The Hudson Valley','The Mohawk Valley','The Connecticut Valley','The Delaware Valley','The Shenandoah Valley','The Schoharie Valley'],explain:'Frelinghuysen ministered in the Raritan Valley of New Jersey beginning in the 1720s.'},
  {type:'mc',era:'First Awakening',q:'Who founded the "Log College" in Pennsylvania?',correct:'William Tennent',wrong:['Gilbert Tennent','Jonathan Edwards','George Whitefield','Theodorus Frelinghuysen','Samuel Davies','Solomon Stoddard'],explain:'William Tennent established the Log College, a one-room academy that trained a generation of revivalist ministers.'},
  {type:'mc',era:'First Awakening',q:'In what year did William Tennent establish the Log College?',correct:'1727',wrong:['1720','1734','1737','1741','1746','1700'],explain:'William Tennent established the Log College in Pennsylvania around 1727.'},
  {type:'mc',era:'First Awakening',q:'Whom did Jonathan Edwards succeed as pastor at Northampton?',correct:'Solomon Stoddard',wrong:['Charles Chauncy','Cotton Mather','Increase Mather','Gilbert Tennent','William Tennent','John Cotton'],explain:'Edwards followed his grandfather Solomon Stoddard as pastor of the Northampton church.'},
  {type:'mc',era:'First Awakening',q:'In what years did the Northampton revival under Edwards occur?',correct:'1734–35',wrong:['1720–21','1740–41','1737–38','1727–28','1692','1746'],explain:'Edwards watched a sudden town-wide awakening in Northampton in 1734–35, recounted in A Faithful Narrative (1737).'},
]}

export function A6_QUESTIONS(){return[
  {type:'mc',era:'First Awakening',q:'What denomination had ordained George Whitefield?',correct:'The Church of England (Anglican)',wrong:['Baptist','Methodist','Presbyterian'],explain:'Whitefield was an Anglican priest, ordained in 1736. He remained Anglican throughout his ministry, though his Calvinist theology distinguished him from John Wesley\'s Arminian Methodism.'},
  {type:'mc',era:'First Awakening',q:'Where did Jonathan Edwards preach "Sinners in the Hands of an Angry God"?',correct:'Enfield, Connecticut',wrong:['Boston, Massachusetts','Princeton, New Jersey','Northampton, Massachusetts'],explain:'Edwards preached the sermon at Enfield, CT on July 8, 1741, at the height of the revival season. Eyewitnesses reported groaning and weeping so loud that Edwards had to pause and call for quiet.'},
  {type:'mc',era:'First Awakening',q:'Which Boston minister was the leading "Old Light" critic of the Awakening?',correct:'Charles Chauncy',wrong:['Solomon Stoddard','Cotton Mather','Increase Mather'],explain:'Chauncy, pastor of Boston\'s First Church, became the revival\'s most prominent opponent. His 1743 Seasonable Thoughts argued the Awakening was dangerous "enthusiasm" — emotional excess — rather than genuine work of the Holy Spirit.'},
  {type:'mc',era:'First Awakening',q:'Who preached "The Danger of an Unconverted Ministry" in 1740?',correct:'Gilbert Tennent',wrong:['Jonathan Edwards','George Whitefield','Charles Chauncy'],explain:'Tennent\'s 1740 sermon accused settled clergy of being spiritually unconverted "Pharisee-Teachers" — and helped precipitate the 1741 Presbyterian split into Old Side and New Side.'},
  {type:'mc',era:'First Awakening',q:'What did Gilbert Tennent\'s 1740 sermon "The Danger of an Unconverted Ministry" argue?',correct:'That many settled ministers were themselves unconverted and therefore unfit to preach',wrong:['That revival meetings should be held in churches rather than fields','That women should be permitted to preach','That unconverted people should be barred from attending church'],explain:'Tennent accused settled clergy of being "Pharisee-Teachers" — outwardly religious but inwardly unconverted. The sermon helped precipitate the 1741 Presbyterian split into Old Side and New Side.'},
  {type:'mc',era:'First Awakening',q:'What happened to the colonial Presbyterian Synod in 1741 as a result of the revival controversy?',correct:'It split into Old Side (anti-revival) and New Side (pro-revival) factions',wrong:['It was dissolved by the colonial governor','It adopted the Westminster Confession for the first time','It merged with the Congregationalists'],explain:'The controversy over Tennent\'s preaching, itinerancy, and the revival\'s methods led the Presbyterian Synod to split in 1741. The division lasted seventeen years, until Old Side and New Side reunited in 1758.'},
  {type:'tf',era:'First Awakening',q:'Benjamin Franklin was a personal friend of George Whitefield and printed many of his sermons, despite being a skeptic.',answer:true,explain:'Franklin and Whitefield maintained a famous friendship despite their theological differences. Franklin published Whitefield\'s sermons profitably and gave to Whitefield\'s Bethesda Orphanage in Georgia. In his autobiography, Franklin tested Whitefield\'s voice-carrying distance by walking away from the crowd.'},
  {type:'tf',era:'First Awakening',q:'The First Great Awakening was largely confined to New England and had little impact on the southern colonies.',answer:false,explain:'Whitefield preached across the entire colonial seaboard, including Georgia, the Carolinas, and Virginia. New Side Presbyterians like Samuel Davies carried revival deep into Virginia, and Separate Baptists like Shubal Stearns transformed the southern religious landscape.'},
  {type:'mc',era:'First Awakening',q:'Which English Anglican priest became the "Grand Itinerant," preaching to massive crowds across all the colonies beginning in 1739?',correct:'George Whitefield',wrong:['John Wesley','Charles Wesley','Gilbert Tennent'],explain:'Whitefield, an ordained Anglican priest, made seven preaching tours of the American colonies. He preached outdoors to crowds that reportedly reached tens of thousands, reaching an estimated 75–80 percent of the colonial population.'},
  {type:'mc',era:'First Awakening',q:'What were the two factions the Great Awakening created within colonial Congregationalism and Presbyterianism?',correct:'New Lights (pro-revival) and Old Lights (anti-revival) — or New Side and Old Side among Presbyterians',wrong:['Whigs and Tories','Separatists and Non-Separatists','High Church and Low Church'],explain:'New Lights embraced revival, personal conversion, and itinerant preaching. Old Lights defended educated clergy, parish boundaries, and formal worship. Among Presbyterians the same divide was called New Side vs. Old Side.'},
  {type:'quote',era:'First Awakening',quote:'"The God that holds you over the pit of hell, much as one holds a spider, or some loathsome insect, over the fire, abhors you, and is dreadfully provoked."',cite:'— Enfield, Connecticut, July 8, 1741',q:'Who preached this sermon?',correct:'Jonathan Edwards',wrong:['George Whitefield','Gilbert Tennent','John Wesley'],explain:'The spider-over-fire image is from "Sinners in the Hands of an Angry God," preached at Enfield on July 8, 1741. It became the defining text of revivalist preaching, though it was atypical of Edwards\'s usual philosophical style.'},
  {type:'mc',era:'First Awakening',q:'Which came first?',correct:'Whitefield began his colonial tour and the revival spread intercolonially',wrong:['Charles Chauncy published Seasonable Thoughts attacking the revival as dangerous enthusiasm'],explain:'Whitefield\'s 1739 tour ignited the Awakening — and it was precisely that revival that provoked Chauncy\'s 1743 critique. The opposition came four years after the fire started.'},
  {type:'mc',era:'First Awakening',q:'On what date did Edwards preach "Sinners in the Hands of an Angry God"?',correct:'July 8, 1741',wrong:['October 31, 1741','July 8, 1740','September 1, 1741','March 15, 1742','July 8, 1739','June 8, 1741'],explain:'Edwards preached the sermon at Enfield, Connecticut on July 8, 1741, at the height of the revival.'},
  {type:'mc',era:'First Awakening',q:'Gilbert Tennent\'s 1740 sermon accused unconverted clergy of being what?',correct:'"Pharisee-Teachers"',wrong:['"Old Lights"','"Half-Way men"','"Hirelings"','"Enthusiasts"','"Antinomians"','"Separatists"'],explain:'Tennent\'s "Danger of an Unconverted Ministry" branded settled clergy as unconverted "Pharisee-Teachers."'},
  {type:'mc',era:'First Awakening',q:'Which college did New Side Presbyterians found in 1746?',correct:'Princeton (College of New Jersey)',wrong:['Harvard','Yale','Dartmouth','Brown','William & Mary','King\'s College'],explain:'New Side Presbyterians founded the College of New Jersey (later Princeton) in 1746.'},
  {type:'mc',era:'First Awakening',q:'Where did Tennent preach "The Danger of an Unconverted Ministry" in 1740?',correct:'Nottingham, Pennsylvania',wrong:['Enfield, Connecticut','Northampton, Massachusetts','Boston, Massachusetts','Princeton, New Jersey','Philadelphia, Pennsylvania','New Haven, Connecticut'],explain:'Tennent preached the sermon at Nottingham, Pennsylvania, in 1740.'},
  {type:'mc',era:'First Awakening',q:'Whitefield\'s open-air voice could reportedly reach crowds of about what size?',correct:'Twenty thousand',wrong:['Two thousand','Five thousand','Fifty thousand','One hundred thousand','Five hundred','Ten million'],explain:'Whitefield\'s voice could reportedly carry to open-field crowds of twenty thousand.'},
]}

export function A7_QUESTIONS(){return[
  {type:'mc',era:'First Awakening',q:'The Great Awakening directly contributed to the founding of which of these colleges?',correct:'Princeton, Brown, Rutgers, and Dartmouth',wrong:['Columbia and Penn','Harvard, Yale, and William & Mary','Georgetown and Notre Dame'],explain:'New Light/New Side parties founded these colleges to train revival-friendly ministers: Princeton (1746), Brown (1764), Rutgers (1766), and Dartmouth (1769).'},
  {type:'mc',era:'First Awakening',q:'Which denomination grew explosively as a result of the Awakening, especially through its "Separate" congregations?',correct:'The Baptists',wrong:['The Anglicans','The Lutherans','The Roman Catholics'],explain:'The Separate Baptists broke from established churches to form congregations of the converted, expanding rapidly in the wake of the revival.'},
  {type:'mc',era:'First Awakening',q:'What were the "Separate" Baptists separating from?',correct:'Established churches, to form gathered congregations of the converted',wrong:['The Baptist General Convention','The Church of England in the South','Quaker meeting houses'],explain:'Separate Baptists rejected formal establishment and required genuine conversion for membership — a direct fruit of the Awakening\'s emphasis on personal experience.'},
  {type:'mc',era:'First Awakening',q:'In what year was Princeton (College of New Jersey) founded?',correct:'1746',wrong:['1636','1764','1769'],explain:'Princeton was chartered in 1746 by New Side Presbyterians eager to train revival-friendly ministers, growing from William Tennent\'s Log College tradition.'},
  {type:'mc',era:'First Awakening',q:'What enduring principle did the Awakening plant that resonated beyond church walls?',correct:'Confidence in personal experience over inherited authority',wrong:['The divine right of kings','Episcopal church governance','Reliance on established clergy for salvation'],explain:'The Awakening\'s emphasis on direct personal conversion created a cultural habit of trusting individual experience — a habit that would echo in the democratic rhetoric of the Revolution.'},
  {type:'tf',era:'First Awakening',q:'The revival split many denominations into pro-revival and anti-revival factions.',answer:true,explain:'New Lights embraced conversion and itinerancy; Old Lights defended educated clergy and parish order. The division ran through nearly every denomination.'},
  {type:'tf',era:'First Awakening',q:'The Great Awakening left no lasting institutional legacy once the revival crowds dispersed.',answer:false,explain:'Its most enduring marks were institutional — a wave of new colleges and the rapid growth of new denominations, especially the Separate Baptists.'},
  {type:'tf',era:'First Awakening',q:'Dartmouth was founded partly to train ministers to Native peoples.',answer:true,explain:'Dartmouth (1769) grew from Eleazar Wheelock\'s Indian charity school and retained a mission to Native education even as it became a broader college.'},
  {type:'mc',era:'First Awakening',q:'Which came first?',correct:'Princeton (College of New Jersey) was founded by New Side Presbyterians',wrong:['Dartmouth was founded, partly to train ministers to Native peoples'],explain:'Princeton was founded in 1746 — the first and most direct fruit of the New Side revival movement. Dartmouth followed in 1769, twenty-three years later, growing from an Indian charity school in New Hampshire.'},
  {type:'mc',era:'First Awakening',q:'Which university did Baptists found in 1764?',correct:'Brown',wrong:['Princeton','Rutgers','Dartmouth','Yale','Harvard','Columbia'],explain:'Brown University was founded by Baptists in 1764, one of four colleges born from the Awakening.'},
  {type:'mc',era:'First Awakening',q:'Rutgers (Queen\'s College), founded in 1766, was established by which group?',correct:'Dutch Reformed',wrong:['Baptists','Presbyterians','Anglicans','Methodists','Congregationalists','Quakers'],explain:'Rutgers, originally Queen\'s College, was founded by the Dutch Reformed in 1766.'},
  {type:'mc',era:'First Awakening',q:'In what year was Dartmouth founded?',correct:'1769',wrong:['1746','1764','1766','1701','1776','1750'],explain:'Dartmouth was founded in 1769, partly to train ministers to Native peoples.'},
  {type:'mc',era:'First Awakening',q:'What was Rutgers originally named?',correct:"Queen's College",wrong:["King's College",'College of New Jersey','College of Rhode Island','Dartmouth College','Brown University','William & Mary'],explain:'Rutgers was founded in 1766 as Queen\'s College by the Dutch Reformed.'},
  {type:'mc',era:'First Awakening',q:'Princeton (College of New Jersey) was founded by which group?',correct:'New Side Presbyterians',wrong:['Baptists','Dutch Reformed','Anglicans','Congregationalists','Quakers','Old Side Presbyterians'],explain:'New Side Presbyterians founded the College of New Jersey (Princeton) in 1746.'},
]}

export function A8_QUESTIONS(){return[
  {type:'mc',era:'Revolution',q:'What name did the British give to the patriot clergy of New England?',correct:'The Black Regiment',wrong:['The Sons of Liberty','The Minute Ministers','The Covenant Corps'],explain:'The nickname referred to the black preaching robes of Congregational and Presbyterian ministers who supported the patriot cause.'},
  {type:'mc',era:'Revolution',q:'Which group of clergy were most likely to remain loyal to the British Crown during the Revolution?',correct:'Anglican clergy',wrong:['Congregational ministers','Presbyterian ministers','Baptist preachers'],explain:'Anglican clergy were bound by ordination oaths to the king; many remained loyalists, and some fled or fell silent during the war.'},
  {type:'mc',era:'Revolution',q:'What was the origin of the nickname "Black Regiment" for patriot preachers?',correct:'Their black preaching robes worn in the pulpit',wrong:['Their association with the Sons of Liberty\'s black cockade','Their use of black-bordered pamphlets','A British military unit they opposed'],explain:'Congregational and Presbyterian ministers wore black Geneva-style robes in the pulpit, giving the British a ready nickname for the clergy who supported independence.'},
  {type:'mc',era:'Revolution',q:'What biblical and theological vocabulary saturated the rhetoric of the American Revolution?',correct:'Covenant, providence, and liberty',wrong:['Atonement, sanctification, and grace','Creation, fall, and redemption','Baptism, communion, and ordination'],explain:'Reformed political theology gave patriot preachers a ready vocabulary — covenant obligations, providential history, and the liberty of God\'s people — that framed resistance as a religious duty.'},
  {type:'tf',era:'Revolution',q:'Quakers and other pacifist groups generally refused to take up arms in the Revolution.',answer:true,explain:'Pacifist traditions like the Quakers declined to fight, even as most other Protestant groups supported independence.'},
  {type:'tf',era:'Revolution',q:'Most Anglican clergy enthusiastically supported the patriot cause.',answer:false,explain:'Bound by ordination oaths to the Crown, most Anglican clergy remained loyalists.'},
  {type:'tf',era:'Revolution',q:'The Awakening\'s habit of mass appeal helped patriot preachers reach cross-colonial audiences.',answer:true,explain:'Revival had taught preachers to address large audiences across colonial lines — a skill directly transferred to the patriot cause.'},
  {type:'mc',era:'Revolution',q:'Why were most Anglican clergy loyalists rather than patriots?',correct:'They were bound by ordination oaths to the king',wrong:['They opposed slavery and saw the Revolution as a slave-holding rebellion','They had all been born in England','The King paid their salaries directly from London'],explain:'Anglican ordination vows included loyalty to the Crown, making open support for independence a violation of one\'s sacred oath. Many clergy fled to Canada or Britain rather than compromise.'},
  {type:'mc',era:'Revolution',q:'Which Lutheran pastor reportedly threw off his robes to reveal a Continental Army uniform?',correct:'Peter Muhlenberg',wrong:['John Witherspoon','Jonathan Mayhew','Francis Asbury','George Whitefield','Samuel Davies','Patrick Henry'],explain:'Peter Muhlenberg, a Lutheran pastor in Virginia, famously declared "there is a time to fight" and joined the Continental Army.'},
  {type:'mc',era:'Revolution',q:'To what denomination did the patriot pastor Peter Muhlenberg belong?',correct:'Lutheran',wrong:['Anglican','Presbyterian','Methodist','Baptist','Congregational','Quaker'],explain:'Peter Muhlenberg was a Lutheran pastor who became one of the most famous patriot clergy of the Revolution.'},
  {type:'mc',era:'Revolution',q:'In which colony did Peter Muhlenberg serve as a pastor?',correct:'Virginia',wrong:['Pennsylvania','Massachusetts','New York','Georgia','Connecticut','Maryland'],explain:'Muhlenberg served in Virginia, where he raised troops for the Continental Army in 1776.'},
  {type:'mc',era:'Revolution',q:'The patriot "Black Regiment" was drawn mainly from which two denominations?',correct:'Congregational and Presbyterian',wrong:['Anglican and Lutheran','Baptist and Quaker','Methodist and Catholic','Dutch Reformed and Lutheran','Quaker and Anglican','Baptist and Methodist'],explain:'The British nicknamed New England\'s patriot Congregational and Presbyterian clergy the "Black Regiment."'},
  {type:'mc',era:'Revolution',q:'Which pacifist group generally refused to take up arms in the Revolution?',correct:'Quakers',wrong:['Baptists','Methodists','Presbyterians','Lutherans','Anglicans','Catholics'],explain:'Quakers and other pacifists refused to take up arms, even as most religious energy ran toward independence.'},
]}

export function A9_QUESTIONS(){return[
  {type:'mc',era:'Founding',q:'Who authored the Virginia Statute for Religious Freedom?',correct:'Thomas Jefferson',wrong:['George Mason','Patrick Henry','James Madison'],explain:'Jefferson drafted the Statute, passed in 1786. He counted it among his three proudest achievements, listed on his tombstone.'},
  {type:'mc',era:'Founding',q:'Whose 1785 "Memorial and Remonstrance" argued against state support for religion in Virginia?',correct:'James Madison',wrong:['Roger Williams','John Adams','Thomas Jefferson'],explain:'Madison\'s "Memorial and Remonstrance Against Religious Assessments" helped defeat a bill to fund Christian teachers and cleared the way for Jefferson\'s Statute.'},
  {type:'mc',era:'Founding',q:'Which dissenting group had been jailed for unlicensed preaching in pre-Revolutionary Virginia?',correct:'Baptists',wrong:['Catholics','Quakers','Lutherans'],explain:'Virginia jailed Baptist preachers for preaching without a license; these persecuted dissenters became strong advocates for disestablishment.'},
  {type:'mc',era:'Founding',q:'What did the Virginia Statute for Religious Freedom declare?',correct:'That no one could be compelled to support any religious worship or penalized for their beliefs',wrong:['That all Virginia churches must register with the state','That Anglicanism remained the established faith but taxes were optional','That only Christian denominations could hold public worship'],explain:'Jefferson\'s Statute ended both compelled financial support for churches and civil penalties for religious belief — a foundational statement of religious liberty.'},
  {type:'mc',era:'Founding',q:'Jefferson listed the Virginia Statute alongside which other two achievements on his tombstone?',correct:'The Declaration of Independence and the founding of the University of Virginia',wrong:['The Constitution and the Louisiana Purchase','The Bill of Rights and the Lewis and Clark Expedition','The Louisiana Purchase and the abolition of the slave trade in D.C.'],explain:'Jefferson chose his epitaph himself: "Author of the Declaration of American Independence, of the Statute of Virginia for Religious Freedom, and Father of the University of Virginia."'},
  {type:'tf',era:'Founding',q:'Thomas Jefferson considered the Virginia Statute for Religious Freedom one of his proudest achievements.',answer:true,explain:'He had it inscribed on his tombstone alongside the Declaration of Independence and the founding of the University of Virginia.'},
  {type:'tf',era:'Founding',q:'Virginia\'s disestablishment became a model for religious liberty in the U.S. Constitution.',answer:true,explain:'The Virginia experiment directly influenced the religious liberty protections soon written into the national framework.'},
  {type:'tf',era:'Founding',q:'It was primarily skeptical Enlightenment figures, not religious groups, who pushed for disestablishment in Virginia.',answer:false,explain:'Persecuted Baptist dissenters were the most aggressive advocates for disestablishment. Madison and Jefferson provided the political and philosophical framework, but Baptist petitions supplied the popular pressure.'},
  {type:'mc',era:'Founding',q:'Which came first?',correct:'Virginia jailed Baptist preachers for unlicensed preaching',wrong:['The Virginia Statute for Religious Freedom was passed into law'],explain:'Virginia was jailing Baptist preachers in 1768 — eighteen years before Jefferson\'s Statute passed in 1786. The very dissenters being persecuted built the popular pressure that produced the statute.'},
  {type:'mc',era:'Founding',q:'Which came first?',correct:'Madison published his "Memorial and Remonstrance" against state support for religion',wrong:['The First Amendment was ratified, extending religious liberty to the national level'],explain:'Madison\'s Remonstrance came in 1785, six years before the First Amendment\'s ratification in 1791. Virginia\'s disestablishment experiment directly shaped the national framework that followed.'},
  {type:'mc',era:'Founding',q:'In what year did Virginia pass the Statute for Religious Freedom?',correct:'1786',wrong:['1776','1777','1785','1791','1789','1833'],explain:'Drafted by Jefferson in 1777, the Virginia Statute for Religious Freedom passed in 1786.'},
  {type:'mc',era:'Founding',q:'In what year was Madison\'s "Memorial and Remonstrance" published?',correct:'1785',wrong:['1786','1776','1791','1777','1789','1781'],explain:'Madison\'s 1785 Memorial and Remonstrance argued against state support for religion in Virginia.'},
  {type:'mc',era:'Founding',q:'In what year did Jefferson draft the Virginia Statute (passed in 1786)?',correct:'1777',wrong:['1776','1785','1786','1791','1781','1789'],explain:'Jefferson drafted the Statute in 1777; it was finally enacted in 1786.'},
  {type:'mc',era:'Founding',q:'Which state was the first to dismantle its established church?',correct:'Virginia',wrong:['Massachusetts','Rhode Island','Connecticut','Pennsylvania','Maryland','New York'],explain:'Virginia became the first state to disestablish its church with the Statute for Religious Freedom in 1786.'},
  {type:'mc',era:'Founding',q:'Besides the Declaration and the Statute, Jefferson named founding what as his proudest achievement?',correct:'The University of Virginia',wrong:['Harvard','William & Mary','The Library of Congress','Monticello','The Smithsonian','The College of New Jersey'],explain:'Jefferson ranked the Statute alongside the Declaration of Independence and the University of Virginia.'},
]}

export function A10_QUESTIONS(){return[
  {type:'mc',era:'Founding',q:'How did the original 1787 Constitution address religion?',correct:'It forbade any religious test for federal office',wrong:['It established Protestantism as the national religion','It guaranteed freedom of worship to all','It made no mention of religion at all'],explain:'The Constitution\'s only reference to religion was the ban on religious tests for office (Article VI) — a striking silence about any official faith.'},
  {type:'mc',era:'Founding',q:'What two religion clauses did the First Amendment establish?',correct:'No establishment of religion, and free exercise of religion',wrong:['Toleration of Protestants and Catholics only','Freedom of worship and freedom from taxation','Separation of church and school'],explain:'The First Amendment (1791) barred Congress from establishing religion or prohibiting its free exercise.'},
  {type:'mc',era:'Founding',q:'Which was the last state to disestablish its official church?',correct:'Massachusetts, in 1833',wrong:['Connecticut, in 1818','Virginia, in 1786','New York, in 1777'],explain:'The First Amendment applied only to the federal government at first; several states kept establishments, with Massachusetts the last to end its in 1833.'},
  {type:'mc',era:'Founding',q:'In what year was the First Amendment ratified?',correct:'1791',wrong:['1776','1803','1820'],explain:'The Bill of Rights, including the First Amendment, was ratified in 1791, four years after the Constitution itself.'},
  {type:'mc',era:'Founding',q:'What voluntary principle did the Constitution and First Amendment together establish for American religion?',correct:'Religion would be voluntary, plural, and free of federal control',wrong:['Religion would be publicly funded but not required','Only Protestant Christianity would receive legal protection','The federal government would promote Christian values without establishing a denomination'],explain:'By refusing to establish a faith and protecting free exercise, the founding documents set a framework of voluntary, plural religion unlike anything in Europe at the time.'},
  {type:'tf',era:'Founding',q:'The First Amendment originally restricted only the federal government, not the states.',answer:true,explain:'Several states maintained religious establishments for decades after 1791; Massachusetts was the last to disestablish, in 1833.'},
  {type:'tf',era:'Founding',q:'The original Constitution named Christianity as the official religion of the United States.',answer:false,explain:'The Constitution mentioned religion only to forbid religious tests for office. It named no official faith.'},
  {type:'tf',era:'Founding',q:'The Constitution\'s silence on religion was accidental — the framers simply forgot to address it.',answer:false,explain:'The silence was deliberate. James Madison and others argued that naming any official faith would corrupt both church and state.'},
  {type:'quote',era:'Founding',quote:'"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof."',cite:'— The First Amendment, 1791',q:'These two clauses are known as the Establishment Clause and the _____ Clause.',correct:'Free Exercise',wrong:['Religious Test','Equal Protection','Toleration'],explain:'The First Amendment\'s twin religion clauses set the framework for American church-state relations — no official religion, and no government interference with worship.'},
  {type:'mc',era:'Founding',q:'In what year did Massachusetts, the last state, disestablish its official church?',correct:'1833',wrong:['1791','1787','1819','1800','1776','1850'],explain:'Massachusetts was the last state to disestablish its church, in 1833.'},
  {type:'mc',era:'Founding',q:'What did the original 1787 Constitution forbid regarding federal office?',correct:'A religious test',wrong:['An established church','A church tax','A bishopric','A loyalty oath','A property requirement','A Sunday law'],explain:'Article VI of the 1787 Constitution forbade any religious test for federal office.'},
  {type:'mc',era:'Founding',q:'The ban on religious tests appears in which Article of the Constitution?',correct:'Article VI',wrong:['Article I','Article II','Article III','Article IV','Article V','Article VII'],explain:'The no-religious-test clause is found in Article VI of the Constitution.'},
  {type:'mc',era:'Founding',q:'How many times did the original 1787 Constitution mention religion?',correct:'Once',wrong:['Twice','Three times','Never','Four times','Seven times','A dozen times'],explain:'The 1787 Constitution mentioned religion only once — to forbid a religious test for office.'},
  {type:'mc',era:'Founding',q:'Congress shall make no law respecting an establishment of religion, or prohibiting the free ___ thereof.',correct:'exercise',wrong:['worship','expression','assembly','practice','conscience','profession'],explain:'The First Amendment\'s two religion clauses bar an establishment and protect the free exercise of religion.'},
]}

export function A11_QUESTIONS(){return[
  {type:'mc',era:'Second Awakening',q:'What was the signature form of frontier revival in the Second Great Awakening?',correct:'The camp meeting',wrong:['The college lecture','The parish catechism','The cathedral mass'],explain:'The camp meeting was a multi-day outdoor gathering where thousands camped, sang, prayed, and heard around-the-clock preaching.'},
  {type:'mc',era:'Second Awakening',q:'Where did the most famous camp meeting of 1801 take place?',correct:'Cane Ridge, Kentucky',wrong:['Enfield, Connecticut','Rochester, New York','Northampton, Massachusetts'],explain:'An estimated 10,000–20,000 gathered at Cane Ridge, Kentucky in 1801 amid intense emotional fervor.'},
  {type:'mc',era:'Second Awakening',q:'Which two denominations grew most rapidly during the Second Great Awakening?',correct:'Methodists and Baptists',wrong:['Presbyterians and Congregationalists','Catholics and Quakers','Anglicans and Lutherans'],explain:'Methodists and Baptists were especially well-suited to the frontier and grew explosively in this period.'},
  {type:'mc',era:'Second Awakening',q:'How many people were estimated to have attended the Cane Ridge camp meeting in 1801?',correct:'10,000 to 20,000',wrong:['About 500','Around 2,000','More than 100,000'],explain:'The crowd of 10,000–20,000 dwarfed the surrounding frontier population — an astonishing assembly for the early American west.'},
  {type:'mc',era:'Second Awakening',q:'How did the Second Awakening\'s theological emphasis differ from the First?',correct:'It shifted from God\'s sovereignty toward human choice and the call to decide for Christ',wrong:['It moved from human choice toward Calvinist predestination','It rejected emotional worship in favor of rational religion','It abandoned conversion narratives in favor of infant baptism'],explain:'Where Edwards had stressed God\'s sovereignty, frontier revivalists increasingly emphasized human decision — a more activist, optimistic Protestantism.'},
  {type:'tf',era:'Second Awakening',q:'Frontier revivalists increasingly emphasized human choice and the call to decide for Christ.',answer:true,explain:'Where Edwards had stressed God\'s sovereignty, the Second Awakening leaned toward human decision — a more activist, optimistic Protestantism.'},
  {type:'tf',era:'Second Awakening',q:'The Second Great Awakening was centered mainly in established East Coast cathedrals.',answer:false,explain:'It was a frontier phenomenon, centered on outdoor camp meetings as Americans pushed west.'},
  {type:'tf',era:'Second Awakening',q:'Jonathan Edwards was the leading figure of the Second Great Awakening.',answer:false,explain:'Edwards died in 1758; he was the central figure of the First Great Awakening of the 1730s–40s. The Second Awakening, beginning around 1800, had different leaders.'},
  {type:'mc',era:'Second Awakening',q:'Which came first?',correct:'The Cane Ridge camp meeting drew an estimated 10,000–20,000 people to the Kentucky frontier',wrong:['Methodists surpassed all other Protestant bodies to become the largest denomination in America'],explain:'Cane Ridge\'s massive gathering came in 1801 — nearly two decades before Methodists became the nation\'s largest Protestant denomination around 1820. The revival fueled the institutional growth that followed.'},
  {type:'mc',era:'Second Awakening',q:'In what year did the Cane Ridge camp meeting take place?',correct:'1801',wrong:['1800','1790','1805','1811','1795','1810'],explain:'The Cane Ridge camp meeting, the largest of the Second Great Awakening, took place in 1801.'},
  {type:'mc',era:'Second Awakening',q:'In what state was the famous Cane Ridge camp meeting held?',correct:'Kentucky',wrong:['Tennessee','Virginia','Ohio','North Carolina','Pennsylvania','Georgia'],explain:'Cane Ridge was held in Kentucky in 1801, drawing an estimated 10,000–20,000 people.'},
  {type:'mc',era:'Second Awakening',q:'Where Edwards stressed God\'s sovereignty, frontier revivalists emphasized human what?',correct:'Choice',wrong:['Reason','Emotion','Tradition','Works','Merit','Effort'],explain:'The Second Great Awakening increasingly emphasized human choice and the call to decide for Christ.'},
  {type:'mc',era:'Second Awakening',q:'Around what year did the Second Great Awakening break out?',correct:'1800',wrong:['1740','1776','1830','1750','1820','1790'],explain:'A second great wave of revival broke out around 1800 as Americans pushed west.'},
  {type:'mc',era:'Second Awakening',q:'Cane Ridge\'s emotional fervor famously included falling, weeping, and what?',correct:'Shouting',wrong:['Dancing','Fasting','Marching','Kneeling','Fainting','Chanting'],explain:'Cane Ridge featured intense emotional fervor — falling, weeping, and shouting.'},
]}

export function A12_QUESTIONS(){return[
  {type:'mc',era:'Second Awakening',q:'What were the traveling Methodist preachers who served the frontier called?',correct:'Circuit riders',wrong:['Lay readers','Class leaders','Camp masters'],explain:'Circuit riders rode endless loops through the wilderness to serve far-flung congregations, led by Bishop Francis Asbury.'},
  {type:'mc',era:'Second Awakening',q:'Which bishop organized and led the Methodist circuit-riding system in America?',correct:'Francis Asbury',wrong:['Charles Finney','George Whitefield','John Wesley'],explain:'Francis Asbury was the central organizing figure of early American Methodism and its circuit system.'},
  {type:'mc',era:'Second Awakening',q:'How did Baptists typically reach the frontier?',correct:'Through farmer-preachers who supported themselves and preached to neighbors',wrong:['Through state-funded missionaries','Through salaried seminary-trained clergy','Through cathedral parishes'],explain:'The Baptist farmer-preacher needed no salary or seminary, making the model cheap, fast, and well-suited to the frontier.'},
  {type:'mc',era:'Second Awakening',q:'What made circuit riders and farmer-preachers more effective on the frontier than traditional settled clergy?',correct:'Low cost and high mobility — they could follow the moving frontier',wrong:['They were supported by state governments','They had more education than settled clergy','They carried printing presses to distribute sermons'],explain:'Methodists and Baptists vastly outgrew older denominations because their systems required neither large salaries nor permanent buildings — just a willing preacher and a horse.'},
  {type:'mc',era:'Second Awakening',q:'What was the result of Methodist and Baptist frontier expansion by the mid-nineteenth century?',correct:'They had become the two largest Protestant bodies in America',wrong:['They merged into a single national church','They were absorbed by the Presbyterian Church','They declined after the frontier closed'],explain:'Their low-cost, high-mobility systems let them vastly outgrow the older, better-educated denominations.'},
  {type:'tf',era:'Second Awakening',q:'By the mid-nineteenth century, Methodists and Baptists had become the two largest Protestant bodies in America.',answer:true,explain:'Their low-cost, high-mobility systems let them vastly outgrow the older, better-educated denominations.'},
  {type:'tf',era:'Second Awakening',q:'Methodists and Baptists succeeded by requiring seminary-educated, salaried clergy on the frontier.',answer:false,explain:'They succeeded precisely by NOT requiring this — circuit riders and farmer-preachers were cheap and mobile.'},
  {type:'tf',era:'Second Awakening',q:'Francis Asbury was born in America and never left the country during his ministry.',answer:false,explain:'Asbury was born in England in 1745 and came to America in 1771 at John Wesley\'s direction. He never returned to England, riding over 300,000 miles across America until his death in 1816.'},
  {type:'mc',era:'Second Awakening',q:'Which came first?',correct:'Francis Asbury arrived in America from England to organize Methodist circuits',wrong:['The Methodist Episcopal Church was formally organized at the Christmas Conference'],explain:'Asbury arrived in 1771 — thirteen years before the Christmas Conference of 1784 formally organized the Methodist Episcopal Church. His decades of circuit-riding built the foundation that conference codified.'},
  {type:'mc',era:'Second Awakening',q:'By what era had Methodists and Baptists become the two largest Protestant bodies in America?',correct:'The mid-nineteenth century',wrong:['The colonial era','The 1700s','The early twentieth century','The Revolution','The 1600s','The Civil War\'s end'],explain:'Low-cost, high-mobility systems let Methodists and Baptists become the two largest Protestant bodies by the mid-nineteenth century.'},
  {type:'mc',era:'Second Awakening',q:'What office did Francis Asbury hold in American Methodism?',correct:'Bishop',wrong:['Circuit rider','Moderator','Elder','Deacon','Presiding elder','Superintendent'],explain:'Bishop Francis Asbury organized and led the Methodist circuit-riding system in America.'},
  {type:'mc',era:'Second Awakening',q:'Methodist traveling preachers rode endless loops known as a what?',correct:'A circuit',wrong:['A parish','A diocese','A presbytery','A district','A mission','A station'],explain:'Circuit riders rode loops — circuits — through the wilderness to serve far-flung frontier congregations.'},
  {type:'mc',era:'Second Awakening',q:'Besides the Methodists, which denomination out-organized the frontier?',correct:'Baptists',wrong:['Presbyterians','Congregationalists','Anglicans','Lutherans','Quakers','Catholics'],explain:'Methodists (circuit riders) and Baptists (farmer-preachers) vastly outgrew the older, better-educated denominations.'},
  {type:'mc',era:'Second Awakening',q:'The Baptist frontier "farmer-preacher" supported himself by what trade?',correct:'Farming',wrong:['Blacksmithing','Teaching','Trading','Carpentry','Medicine','Law'],explain:'The Baptist farmer-preacher supported himself by farming and preached to his neighbors without salary or seminary.'},
]}

export function A13_QUESTIONS(){return[
  {type:'mc',era:'Second Awakening',q:'What name was given to the region of upstate New York that had been swept so repeatedly by revival it was said to have no spiritual fuel left?',correct:'The Burned-Over District',wrong:['The Great Awakening Belt','The Anxious Frontier','The Revival Corridor'],explain:'Western New York was so frequently swept by revival that it was said to have no spiritual "fuel" left — hence "burned over." It was also the birthplace of Joseph Smith\'s new religion.'},
  {type:'mc',era:'Second Awakening',q:'What was the "anxious bench" in Finney\'s revival meetings?',correct:'A front pew reserved for nearly-converted persons who sat under prayer',wrong:['A bench outside the church where sinners waited to be baptized','A pew designated for those under church discipline','A seat reserved for the preacher during long meetings'],explain:'The anxious bench was one of Finney\'s signature "new measures" — placing the almost-converted in a conspicuous spot to heighten the moment of decision.'},
  {type:'mc',era:'Second Awakening',q:'How did Finney\'s theology depart from the Calvinist tradition?',correct:'He taught that sinners had the natural ability to choose God and that revival was the predictable result of using the right means',wrong:['He taught that God alone controlled conversion and revival was entirely miraculous','He embraced baptismal regeneration over conversion experience','He rejected revival altogether in favor of sacramental worship'],explain:'Finney rejected Calvinist sovereignty, insisting revival was not a miracle but the predictable result of correct methods — a major shift that set the template for American mass evangelism.'},
  {type:'mc',era:'Second Awakening',q:'What did Finney call his revival techniques — the anxious bench, protracted meetings, and public prayer for the unconverted by name?',correct:'New measures',wrong:['Holy methods','Sacred techniques','Spiritual disciplines'],explain:'Finney\'s "new measures" were controversial among traditional clergy but proved highly effective, spreading his revival influence far beyond upstate New York.'},
  {type:'mc',era:'Second Awakening',q:'Whose twentieth-century crusade methods descended most directly from Finney\'s innovations in mass evangelism?',correct:'Billy Graham\'s',wrong:['D. L. Moody\'s','Jonathan Edwards\'','George Whitefield\'s'],explain:'Finney set the template — the large public gathering, the invitation to decide, the call forward — that Billy Graham\'s crusades a century later would perfect and globalize.'},
  {type:'tf',era:'Second Awakening',q:'Before becoming a revivalist, Charles Grandison Finney was trained as a lawyer.',answer:true,explain:'His legal training shaped his preaching style — direct and argumentative, addressing sinners the way a prosecutor addresses a jury.'},
  {type:'tf',era:'Second Awakening',q:'Finney\'s theology was firmly within the Calvinist tradition, stressing God\'s sovereignty in salvation.',answer:false,explain:'Finney broke sharply from Calvinism, insisting that sinners had the natural ability to choose God and that revival was a predictable human technique, not a divine miracle.'},
  {type:'tf',era:'Second Awakening',q:'Finney\'s "protracted meetings" typically lasted only a few hours.',answer:false,explain:'Protracted meetings ran for days at a stretch — continuous services designed to sustain revival momentum until conversions occurred.'},
  {type:'mc',era:'Second Awakening',q:'Which came first?',correct:'Finney\'s Rochester revival marked the peak of his New York campaigns',wrong:['Finney published his Lectures on Revivals of Religion, systematizing revival as a technique'],explain:'The Rochester revival came in 1830; the Lectures followed five years later in 1835. Finney lived the method before he wrote it — the book systematized what the revivals had already demonstrated.'},
  {type:'mc',era:'Second Awakening',q:'In which state did Finney conduct his famous "new measures" revivals?',correct:'New York',wrong:['Kentucky','Massachusetts','Ohio','Pennsylvania','Connecticut','Vermont'],explain:'Finney swept through upstate New York — the "Burned-Over District" — in the 1820s and 1830s.'},
  {type:'mc',era:'Second Awakening',q:'What were Finney\'s multi-day revival services designed to sustain momentum called?',correct:'Protracted meetings',wrong:['Camp meetings','Anxious benches','Hush arbors','Watch nights','Class meetings','Love feasts'],explain:'Protracted meetings ran for days to sustain revival momentum until conversions occurred.'},
  {type:'mc',era:'Second Awakening',q:'What was Charles Finney\'s middle name?',correct:'Grandison',wrong:['Gardner','Granger','Gordon','Graham','Garfield','Goodwin'],explain:'Charles Grandison Finney was a lawyer-turned-revivalist of the Second Great Awakening.'},
  {type:'mc',era:'Second Awakening',q:'Which theological system\'s view of conversion did Finney reject?',correct:'Calvinism',wrong:['Arminianism','Lutheranism','Pelagianism','Pietism','Methodism','Catholicism'],explain:'Finney rejected the Calvinist view that conversion was God\'s sovereign act, teaching that sinners could choose God.'},
  {type:'mc',era:'Second Awakening',q:'Finney taught that revival was not a miracle but the predictable result of using the right what?',correct:'Means',wrong:['Prayers','Doctrines','Leaders','Emotions','Seasons','Texts'],explain:'Finney argued revival was the predictable result of using the right means — not a sovereign miracle.'},
]}

export function A14_QUESTIONS(){return[
  {type:'mc',era:'Critics of Revival',q:"What was Charles Hodge's primary theological objection to Finney's revivalism?",correct:"That Finney's teaching on human ability was Pelagianism — the heresy that humans could save themselves without divine grace",wrong:['That Finney preached too often and exhausted his congregations','That Finney held services outdoors rather than in churches','That Finney used music and singing in worship'],explain:"Hodge argued that Finney's claim that sinners had the natural ability to choose God contradicted the Calvinist doctrine of total depravity and was essentially the ancient Pelagian heresy condemned at the Council of Carthage (418)."},
  {type:'mc',era:'Critics of Revival',q:"What was the name of Nevin's 1843 attack on Finney's new measures?",correct:'The Anxious Bench',wrong:['Christianity and Liberalism','The New Measures Examined','The Uneasy Conscience'],explain:"Nevin's The Anxious Bench (1843) was a point-by-point theological refutation of Finney's revival techniques, arguing they represented a false theology of conversion as psychological crisis rather than sacramental incorporation into the church."},
  {type:'mc',era:'Critics of Revival',q:'At which seminary did Nevin and Schaff develop the Mercersburg Theology?',correct:'The German Reformed seminary in Mercersburg, Pennsylvania',wrong:['Princeton Theological Seminary in New Jersey','Yale Divinity School in Connecticut','Andover Theological Seminary in Massachusetts'],explain:'The tiny German Reformed seminary in Mercersburg, Pennsylvania was an unlikely center of theological sophistication. Nevin joined its faculty in 1840; Philip Schaff, trained in Germany and Switzerland, arrived in 1844.'},
  {type:'mc',era:'Critics of Revival',q:'What did Charles Hodge famously boast about Princeton Seminary?',correct:"That no new idea had ever originated there — Princeton's job was to guard orthodoxy, not innovate",wrong:["That Princeton had trained more ministers than any other seminary in America","That Princeton's library was the largest in the Western Hemisphere","That no Princeton graduate had ever left the Presbyterian Church"],explain:"Hodge's boast was a theological statement: Princeton's purpose was the preservation and transmission of confessional Reformed orthodoxy as codified in the Westminster Standards, not theological development."},
  {type:'mc',era:'Critics of Revival',q:"What was the Mercersburg Theology's alternative to revivalist conversion?",correct:'That true Christianity was received through the sacraments and the life of the church as a living organism',wrong:['That conversion required a dramatic emotional experience like those at Cane Ridge','That baptism as an infant was sufficient without any personal faith','That only trained clergy could validly administer the means of grace'],explain:'Nevin argued that the church — not the revival meeting — was the proper context for Christian formation, and that the sacraments — not the anxious bench — were the means by which Christ communicated himself to believers.'},
  {type:'tf',era:'Critics of Revival',q:'Charles Hodge and John Williamson Nevin criticized Finney from the same theological direction.',answer:false,explain:'Both criticized Finney, but from incompatible directions: Hodge from strict Calvinist confessionalism, Nevin from a high-church sacramental and historical perspective. Their own theologies were quite different from each other.'},
  {type:'tf',era:'Critics of Revival',q:'Philip Schaff brought European Reformed scholarly training to the Mercersburg faculty.',answer:true,explain:'Schaff was trained in Germany and Switzerland under leading Protestant scholars. He joined Mercersburg in 1844 and brought a historically sophisticated ecumenical vision that was unlike anything else in 19th-century America.'},
  {type:'tf',era:'Critics of Revival',q:"Hodge's three-volume Systematic Theology was built on the Westminster Confession.",answer:true,explain:"Hodge's theology was explicitly confessional Reformed, structured around and in defense of the Westminster Standards. It became the definitive statement of Old School Presbyterian orthodoxy."},
  {type:'quote',era:'Critics of Revival',quote:'"The system of the anxious bench…is at war with the very genius of the gospel, and hostile to the interests of a sound religious experience."',cite:'— John Williamson Nevin, The Anxious Bench, 1843',q:"Nevin's core argument was that the anxious bench replaced what with what?",correct:'The sacraments and church life with manufactured psychological crisis',wrong:['Preaching with emotional music','Scripture with church tradition','Calvinist doctrine with Arminian free will'],explain:'Nevin argued the anxious bench assumed conversion was a psychological event produced by the right pressure, replacing the proper means of grace — word and sacrament in the life of the church.'},
  {type:'mc',era:'Critics of Revival',q:'At which seminary did Charles Hodge teach?',correct:'Princeton',wrong:['Mercersburg','Yale','Andover','Union','Harvard','Gettysburg'],explain:'Charles Hodge was the dominant theologian of 19th-century Presbyterianism at Princeton Seminary.'},
  {type:'mc',era:'Critics of Revival',q:'Which ancient heresy did Hodge charge against Finney\'s theology?',correct:'Pelagianism',wrong:['Arianism','Donatism','Nestorianism','Gnosticism','Montanism','Sabellianism'],explain:'Hodge charged that Finney\'s teaching on human ability was Pelagianism — the heresy that humans can save themselves.'},
  {type:'mc',era:'Critics of Revival',q:'What was the title of John Williamson Nevin\'s 1843 critique of Finney?',correct:'The Anxious Bench',wrong:['The Mystical Presence','Seasonable Thoughts','The Bloudy Tenent','Cases of Conscience','The Liberator','A Faithful Narrative'],explain:'Nevin\'s The Anxious Bench (1843) argued Finney\'s new measures were a false theology of conversion.'},
  {type:'mc',era:'Critics of Revival',q:'With which church historian did Nevin develop the Mercersburg Theology?',correct:'Philip Schaff',wrong:['Charles Hodge','Charles Finney','John Nelson Darby','William Miller','Joseph Smith','Lyman Beecher'],explain:'Nevin and Philip Schaff developed the Mercersburg Theology at a German Reformed seminary in Pennsylvania.'},
  {type:'mc',era:'Critics of Revival',q:'The Mercersburg seminary belonged to which denomination?',correct:'German Reformed',wrong:['Dutch Reformed','Presbyterian','Lutheran','Methodist','Episcopal','Congregational'],explain:'Nevin and Schaff taught at a small German Reformed seminary at Mercersburg, Pennsylvania.'},
]}

export function A15_QUESTIONS(){return[
  {type:'mc',era:'New Movements',q:'In what year did Joseph Smith found the Church of Jesus Christ of Latter-day Saints?',correct:'1830',wrong:['1850','1844','1820'],explain:'Smith organized the church on April 6, 1830, in western New York — the heart of the Burned-Over District that had also produced Finney\'s revivals.'},
  {type:'mc',era:'New Movements',q:'What was the "Great Disappointment" of 1844?',correct:'The passing of William Miller\'s predicted date for Christ\'s return without the event occurring',wrong:['The collapse of the Burned-Over District revivals','The failure of the Cane Ridge camp meeting to spread nationwide','The dissolution of the LDS Church in its early years'],explain:'Miller\'s following of up to 100,000 was devastated when Christ did not return on the predicted date. Some went on to form Seventh-day Adventism from the wreckage.'},
  {type:'mc',era:'New Movements',q:'William Miller was a lay preacher of which denomination?',correct:'Baptist',wrong:['Presbyterian','Methodist','Congregationalist'],explain:'Miller was a Baptist lay preacher, not a formally trained minister. His movement was interdenominational — followers came from many Protestant backgrounds.'},
  {type:'tf',era:'New Movements',q:'William Miller was a Presbyterian minister who predicted Christ\'s return based on the book of Daniel.',answer:false,explain:'Miller was a Baptist lay preacher. He was not formally trained clergy, and his following was interdenominational.'},
  {type:'tf',era:'New Movements',q:'The same region of New York that produced Finney\'s revivals also gave birth to the LDS Church.',answer:true,explain:'Western New York — the "Burned-Over District" — was the epicenter of both movements. The intense religious ferment that fueled Finney\'s revivals also produced Joseph Smith\'s new religion.'},
  {type:'mc',era:'New Movements',q:'What system did John Nelson Darby develop that would later dominate American fundamentalism?',correct:'Dispensationalism — a framework dividing history into distinct ages of God\'s dealings with humanity',wrong:['Mercersburg Theology','Christian Realism','The Social Gospel'],explain:'Darby developed dispensationalism among the Plymouth Brethren before making multiple American tours in the 1860s–70s, planting the system in evangelical networks.'},
  {type:'tf',era:'New Movements',q:'John Nelson Darby was born in Ireland.',answer:true,explain:'Darby was an Irish-born Plymouth Brethren minister who developed dispensationalism and made multiple tours of America in the 1860s and 1870s.'},
  {type:'mc',era:'New Movements',q:'In what religious community did John Nelson Darby develop his dispensationalist framework?',correct:'The Plymouth Brethren',wrong:['The Methodists','The Baptists','The Reformed Presbyterians'],explain:'Darby was a Plymouth Brethren minister. His dispensationalist system spread from the Brethren into broader evangelical networks, especially through American prophetic Bible conferences.'},
  {type:'mc',era:'New Movements',q:'Which came first?',correct:'Joseph Smith organized the Church of Jesus Christ of Latter-day Saints in western New York',wrong:['John Nelson Darby began his American lecture tours spreading dispensationalism'],explain:'Smith organized the LDS Church in 1830 — more than thirty years before Darby\'s American tours of the 1860s and 1870s. Both men responded to the same era of millennial expectation but in entirely different ways.'},
  {type:'mc',era:'New Movements',q:'What scripture did Joseph Smith claim in founding the LDS Church?',correct:'The Book of Mormon',wrong:['The Book of Daniel','The Doctrine of Dispensations','The Great Disappointment','The Pearl Catechism','The Westminster Confession','The Book of Concord'],explain:'Joseph Smith founded the LDS Church in 1830, claiming new scripture — the Book of Mormon — and continuing revelation.'},
  {type:'mc',era:'New Movements',q:'In what year did William Miller predict Christ would return?',correct:'1844',wrong:['1830','1843','1860','1875','1840','1850'],explain:'Miller calculated from Daniel and Revelation that Christ would return in 1844 — the "Great Disappointment."'},
  {type:'mc',era:'New Movements',q:'Miller calculated his date from the book of Daniel and which other book?',correct:'Revelation',wrong:['Isaiah','Ezekiel','Matthew','Genesis','Psalms','Acts'],explain:'Miller drew his prophetic timeline from the books of Daniel and Revelation.'},
  {type:'mc',era:'New Movements',q:'Some of Miller\'s followers went on to form which denomination?',correct:'Seventh-day Adventism',wrong:['Mormonism','Jehovah\'s Witnesses','the Disciples of Christ','Christian Science','Pentecostalism','the Shakers'],explain:'From the wreckage of the Great Disappointment, some Millerites formed Seventh-day Adventism.'},
  {type:'mc',era:'New Movements',q:'In which region did Joseph Smith organize the LDS Church?',correct:'Western New York',wrong:['Utah','Ohio','Illinois','Missouri','Vermont','Pennsylvania'],explain:'Joseph Smith organized the LDS Church in western New York in 1830 — the same revival-soaked region as Finney.'},
]}

export function A16_QUESTIONS(){return[
  {type:'mc',era:'Reform Era',q:'What was the "Benevolent Empire"?',correct:'The network of voluntary reform societies produced by Second Awakening activism',wrong:['Britain\'s colonial mission to Christianize the empire','The Methodist church\'s organizational structure','A network of Catholic charities in Eastern cities'],explain:'The Benevolent Empire included the American Bible Society, American Tract Society, and dozens of organizations targeting temperance, Sabbath observance, prison reform, and more.'},
  {type:'mc',era:'Reform Era',q:'In what year was the American Bible Society founded?',correct:'1816',wrong:['1835','1800','1830'],explain:'The American Bible Society (1816) was among the first major Benevolent Empire organizations, distributing Bibles widely across the new nation.'},
  {type:'mc',era:'Reform Era',q:'Which revivalist declared that slaveholders should be barred from communion?',correct:'Charles Finney',wrong:['Theodore Dwight Weld','Lyman Beecher','William Lloyd Garrison'],explain:'Finney\'s antislavery position was rooted directly in his revival theology — that sin must be confronted, and slaveholding was sin. He treated it as a disqualification from the Lord\'s Supper.'},
  {type:'mc',era:'Reform Era',q:'Which activists combined Scripture-based theology with financial backing to fund direct antislavery organizing in the 1830s–40s?',correct:'Theodore Dwight Weld and the Tappan brothers',wrong:['Charles Finney and Lyman Beecher','William Lloyd Garrison and Frederick Douglass','Harriet Beecher Stowe and Harriet Tubman'],explain:'Weld and the Tappan brothers united evangelical theology with grassroots organizing — distinguishing them from the more secular or journalistic wing of the abolitionist movement.'},
  {type:'mc',era:'Reform Era',q:'What did evangelical abolitionists like Theodore Dwight Weld and the Tappan brothers argue about slavery?',correct:'That slavery was sin, arguing directly from Scripture',wrong:['That slavery was economically unsustainable','That slavery violated natural law but not Scripture','That slavery should end gradually over fifty years'],explain:'Weld and the Tappan brothers combined financial backing with theological argument, insisting the Bible condemned slavery as sin.'},
  {type:'mc',era:'Reform Era',q:'Why did many women gain organizational experience through Benevolent Empire reform societies?',correct:'The societies gave women their first sphere of organized public action',wrong:['Women were legally required to lead temperance societies','Reform societies were the only organizations that paid women equal wages','Most male reformers refused to participate, leaving women to organize alone'],explain:'Through voluntary reform societies women learned to manage meetings, coordinate networks, and fundraise — skills many carried directly into the later women\'s rights movement.'},
  {type:'tf',era:'Reform Era',q:'Many women found in Benevolent Empire voluntary societies their first sphere of organized public action.',answer:true,explain:'The reform societies gave women organizational experience that fueled the later suffrage and women\'s rights movements.'},
  {type:'tf',era:'Reform Era',q:'The Second Awakening\'s theology was essentially compatible with the continued existence of slavery.',answer:false,explain:'Its core logic — every soul has equal worth before God, and every person has the natural ability to choose good — was in direct tension with slavery. That tension eventually tore the churches apart.'},
  {type:'tf',era:'Reform Era',q:'Theodore Dwight Weld and the Tappan brothers funded antislavery organizing.',answer:true,explain:'Lewis and Arthur Tappan were wealthy New York merchants who bankrolled Weld\'s antislavery campaigns and other abolitionist organizing.'},
  {type:'mc',era:'Reform Era',q:'Which came first?',correct:'The American Bible Society was founded as part of the Benevolent Empire',wrong:['Theodore Dwight Weld published American Slavery As It Is, marshaling evidence against slavery'],explain:'The American Bible Society was founded in 1816; Weld\'s antislavery tract came twenty-three years later in 1839. The arc from Bible distribution to direct abolitionist confrontation traces the Benevolent Empire\'s radicalization.'},
  {type:'mc',era:'Reform Era',q:'In what year was the American Tract Society founded?',correct:'1825',wrong:['1816','1830','1820','1810','1840','1850'],explain:'The American Tract Society (1825) was a leading organization of the Benevolent Empire.'},
  {type:'mc',era:'Reform Era',q:'Besides temperance and prison reform, the Benevolent Empire promoted observance of what?',correct:'The Sabbath',wrong:['Lent','Dietary law','Fasting days','The tithe','Communion','Holy days'],explain:'Benevolent Empire societies targeted temperance, Sabbath observance, and prison reform, among other causes.'},
  {type:'mc',era:'Reform Era',q:'Which brothers funded antislavery organizing alongside Theodore Dwight Weld?',correct:'The Tappan brothers',wrong:['The Beecher brothers','The Grimké sisters','The Wesley brothers','The Allen brothers','The Garrison brothers','The Finney brothers'],explain:'The Tappan brothers and Theodore Dwight Weld funded evangelical antislavery organizing.'},
  {type:'mc',era:'Reform Era',q:'Evangelical abolitionists argued from Scripture that slavery was what?',correct:'Sin',wrong:['A necessary evil','Lawful','Divinely ordained','A civil matter','Inevitable','Temporary'],explain:'Evangelical abolitionists like Weld and the Tappans argued from Scripture that slavery was sin.'},
  {type:'mc',era:'Reform Era',q:'The Benevolent Empire grew out of the optimism of which movement?',correct:'The Second Great Awakening',wrong:['The First Great Awakening','The Reformation','The Civil Rights Movement','The Social Gospel','Pentecostalism','The Puritan era'],explain:'The Second Awakening\'s activist, optimistic theology produced the Benevolent Empire of reform societies.'},
]}

export function A17_QUESTIONS(){return[
  {type:'mc',era:'Slavery & Schism',q:'In what year did the Methodist Episcopal Church split over slavery?',correct:'1844',wrong:['1831','1858','1861'],explain:'The split came in 1844 over whether a slaveholding bishop, James O. Andrew, could continue in office. The Methodist Episcopal Church South was organized the following year.'},
  {type:'mc',era:'Slavery & Schism',q:'What specific issue triggered the Methodist Episcopal Church\'s 1844 split?',correct:'Whether a slaveholding bishop could continue in office',wrong:['Whether Black members could be ordained as clergy','Whether the church should condemn slavery from the pulpit','Whether Southern congregations would fund antislavery missions'],explain:'Bishop James O. Andrew had inherited enslaved people through marriage. Northern Methodists insisted he step aside; Southern Methodists refused. The impasse broke the denomination.'},
  {type:'mc',era:'Slavery & Schism',q:'In what year was the Southern Baptist Convention formed?',correct:'1845',wrong:['1870','1831','1861'],explain:'Southern Baptists broke from the national convention in 1845 after missionary boards refused to appoint slaveholding missionaries.'},
  {type:'mc',era:'Slavery & Schism',q:'What theological argument did Southern clergy develop to defend slavery?',correct:'A "biblical defense of slavery" marshaling specific Scripture passages to argue slavery was divinely sanctioned',wrong:['A natural law argument based on Enlightenment reason','An economic argument about the necessity of plantation agriculture','A historical argument citing Roman and Greek precedent'],explain:'Southern ministers compiled passages — Noah\'s curse on Canaan, Paul\'s instructions to slaves — to argue the Bible endorsed slavery. Northerners countered with the Bible\'s broader liberation themes.'},
  {type:'mc',era:'Slavery & Schism',q:'What does the timing of the denominational splits — Methodists in 1844, Baptists in 1845 — reveal?',correct:'The churches split over slavery before the nation did — presaging the Civil War by sixteen years',wrong:['Church unity held longer than national unity','The splits were primarily over governance rather than slavery','The denominations reunited before the war began'],explain:'The denominational fractures of the 1840s were a theological preview of the national war of 1861. The churches could not resolve what the nation would settle by bloodshed.'},
  {type:'tf',era:'Slavery & Schism',q:'The major Protestant denominations divided over slavery before the Civil War.',answer:true,explain:'The Methodists split in 1844 and the Baptists in 1845 — sixteen years before the Civil War began.'},
  {type:'tf',era:'Slavery & Schism',q:'Only Southern Christians used the Bible to defend their position on slavery; Northern abolitionists relied entirely on secular arguments.',answer:false,explain:'Both sides used the Bible extensively. Southerners cited specific passages defending slavery; Northerners countered with the Bible\'s broader themes of liberation and human dignity.'},
  {type:'tf',era:'Slavery & Schism',q:'The denominational splits of the 1840s were a theological preview of the national war that came in 1861.',answer:true,explain:'The Methodist and Baptist splits presaged the Civil War by sixteen years — the churches could not hold together what the nation was already tearing apart.'},
  {type:'mc',era:'Slavery & Schism',q:'Which came first?',correct:'The Methodists divided over whether a slaveholding bishop could continue in office',wrong:['Southern Presbyterians formed their own General Assembly at the outbreak of the Civil War'],explain:'The Methodist split came in 1844 — seventeen years before Southern Presbyterians separated in 1861. The churches divided over slavery long before the nation went to war over it.'},
  {type:'mc',era:'Slavery & Schism',q:'The 1844 Methodist split centered on which slaveholding bishop?',correct:'James O. Andrew',wrong:['Francis Asbury','Richard Allen','Peter Cartwright','Leonidas Polk','William Capers','Joshua Soule'],explain:'The Methodist Episcopal Church split in 1844 over whether slaveholding bishop James O. Andrew could remain in office.'},
  {type:'mc',era:'Slavery & Schism',q:'The Southern Methodists formed which church in 1845?',correct:'The Methodist Episcopal Church South',wrong:['The Southern Baptist Convention','The African Methodist Episcopal Church','The Cumberland Presbyterian Church','The Free Methodist Church','The Christian Methodist Episcopal Church','The Wesleyan Methodist Church'],explain:'The Methodist Episcopal Church South was founded in 1845 after the split over slaveholding.'},
  {type:'mc',era:'Slavery & Schism',q:'The 1845 Baptist split over slavery created which body?',correct:'The Southern Baptist Convention',wrong:['The American Baptist Convention','The National Baptist Convention','The Free Will Baptists','The Primitive Baptists','The Separate Baptists','The Northern Baptist Convention'],explain:'The Southern Baptist Convention formed in 1845 after Southern boards rejected a slaveholding missionary candidate.'},
  {type:'mc',era:'Slavery & Schism',q:'The denominational splits previewed the national war that began in 1861 at which fort?',correct:'Fort Sumter',wrong:['Fort Ticonderoga','Fort McHenry','Fort Donelson','Fort Pillow','Fort Henry','Fort Pulaski'],explain:'The theological preview of the 1840s became national war at Fort Sumter in 1861.'},
  {type:'mc',era:'Slavery & Schism',q:'The two largest Protestant denominations that split over slavery were the Baptists and the what?',correct:'Methodists',wrong:['Presbyterians','Episcopalians','Lutherans','Congregationalists','Quakers','Catholics'],explain:'The Methodists (1844) and Baptists (1845) — the two largest Protestant bodies — split over slavery before the nation did.'},
]}

export function A18_QUESTIONS(){return[
  {type:'mc',era:'Abolition',q:'Who founded the African Methodist Episcopal Church in 1816?',correct:'Richard Allen',wrong:['Frederick Douglass','Absalom Jones','Denmark Vesey'],explain:'Allen founded the AME after Black worshipers were pulled from their knees at St. George\'s Methodist Church. It became the first major Black-owned institution in America.'},
  {type:'mc',era:'Abolition',q:'How did Frederick Douglass describe the two versions of American Christianity?',correct:'A "slaveholding religion" that blessed the whip, and the true Christianity of Christ that condemned slavery',wrong:['A Northern faith and a Southern faith equally valid in their own contexts','A white religion of power and a Black religion of suffering','A Catholic tradition and a Protestant tradition divided by race'],explain:'In the appendix to his Narrative, Douglass made this pointed distinction — separating the Christianity used to justify slavery from the genuine Christianity of Jesus, which he believed condemned it.'},
  {type:'mc',era:'Abolition',q:'What biblical figure did Harriet Tubman identify with, and why?',correct:'Moses, because like Moses she led her people out of bondage',wrong:['Deborah, because she was a female leader in a male world','Miriam, because she sang at the water\'s edge after the crossing','Esther, because she risked her life before a hostile ruler'],explain:'Tubman called herself Moses — the Exodus story was not allegory for enslaved Christians but promise. She made nineteen trips back into slave territory and led over 300 people to freedom.'},
  {type:'mc',era:'Abolition',q:'What were "hush arbor" gatherings?',correct:'Secret worship meetings held by enslaved people, often in the woods, outside slaveholder supervision',wrong:['Baptist camp meetings on Southern plantations with white oversight','AME Church services held in border-state cities','Quaker abolitionist meetings in the North'],explain:'Enslaved people often had to worship secretly; hush arbors were hidden gatherings where they sang, prayed, and sustained a faith that held together hope and resistance.'},
  {type:'mc',era:'Abolition',q:'What was the Underground Railroad?',correct:'A network of safe houses and routes by which enslaved people escaped to the North',wrong:['A secret tunnel system beneath Southern plantations','A code name for Northern abolitionist newspapers','A system of legal manumission arranged by Quaker lawyers'],explain:'The Underground Railroad was a network of safe houses, guides, and routes — Harriet Tubman was its most famous conductor, making nineteen trips back into the South.'},
  {type:'mc',era:'Abolition',q:'Which figure was NOT among the major Christian voices of the abolitionist movement?',correct:'Thomas Jefferson',wrong:['William Lloyd Garrison','Harriet Beecher Stowe','Theodore Dwight Weld'],explain:'Jefferson was a Deist who owned enslaved people and did not champion abolitionism. Garrison, Stowe, and Weld were all Christians who drew on Scripture in their antislavery arguments.'},
  {type:'tf',era:'Abolition',q:'Frederick Douglass was a formerly enslaved man.',answer:true,explain:'He escaped slavery in Maryland in 1838 and became the most powerful orator and writer of the abolitionist movement.'},
  {type:'tf',era:'Abolition',q:'The abolitionist movement was primarily led by secular Enlightenment thinkers rather than Christians.',answer:false,explain:'The movement was deeply Christian. Garrison, Stowe, Weld, Douglass, and Tubman all drew on religious conviction. The most powerful abolitionists were not skeptics but devout believers.'},
  {type:'tf',era:'Abolition',q:'Harriet Tubman led hundreds of enslaved people to freedom on the Underground Railroad.',answer:true,explain:'Tubman made nineteen trips back into the South and led over 300 people to freedom, never losing a passenger. She called herself Moses.'},
  {type:'mc',era:'Abolition',q:'Which came first?',correct:'William Lloyd Garrison began publishing The Liberator',wrong:['Harriet Beecher Stowe published Uncle Tom\'s Cabin'],explain:'Garrison launched The Liberator in 1831 — twenty-one years before Stowe\'s 1852 novel. Garrison\'s journalism built the abolitionist movement over two decades; Stowe\'s novel brought it to the mass public.'},
  {type:'mc',era:'Abolition',q:'In which city did Richard Allen found the African Methodist Episcopal Church?',correct:'Philadelphia',wrong:['Boston','New York','Baltimore','Charleston','Richmond','Atlanta'],explain:'Richard Allen founded the AME Church in Philadelphia in 1816 after Black worshipers were pulled from prayer.'},
  {type:'mc',era:'Abolition',q:'Which antislavery newspaper did William Lloyd Garrison begin publishing in 1831?',correct:'The Liberator',wrong:['The North Star','The Emancipator','The Anti-Slavery Standard','The Tribune','The Crisis','The Appeal'],explain:'Garrison began publishing The Liberator in 1831, a landmark of the Christian abolitionist movement.'},
  {type:'mc',era:'Abolition',q:'Frederick Douglass called the false faith that blessed slavery a "___ religion."',correct:'slaveholding',wrong:['nominal','civil','Southern','pharisaical','worldly','lukewarm'],explain:'Douglass distinguished a "slaveholding religion" from the true Christianity of Christ, which condemned slavery.'},
  {type:'mc',era:'Abolition',q:'About how many enslaved people did Harriet Tubman lead to freedom?',correct:'About 70',wrong:['About 300','About 1,000','About 12','About 500','About 150','About 40'],explain:'Tubman led approximately 70 enslaved people to freedom on the Underground Railroad.'},
  {type:'mc',era:'Abolition',q:'In what year did Richard Allen found the AME Church?',correct:'1816',wrong:['1801','1831','1845','1808','1820','1791'],explain:'Richard Allen founded the AME Church — the first major institution owned and governed by Black Americans — in 1816.'},
]}

export function A19_QUESTIONS(){return[
  {type:'mc',era:'Civil War & Reconstruction',q:'What did Lincoln observe about both sides of the Civil War in the Second Inaugural Address?',correct:'That both sides read the same Bible and prayed to the same God',wrong:['That the North fought under God\'s direct command','That the South had abandoned Christianity entirely','That neither side deserved divine favor'],explain:'Lincoln\'s careful refusal to claim God simply for the Union side — noting both sides prayed to the same God — made the address theologically remarkable and unusual for any political speech.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'How did Lincoln interpret the meaning of the Civil War in the Second Inaugural?',correct:'As God\'s judgment on the whole nation for the sin of slavery',wrong:['As God\'s reward for the Union\'s righteousness','As divine punishment for Northern industrial greed','As a war required by Enlightenment principles of democratic government'],explain:'Lincoln suggested the war\'s terrible cost was God\'s just judgment on both North and South for the national sin of slavery — a level of theological depth rare in any political speech.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'How much did AME Church membership grow between 1860 and 1870?',correct:'From 20,000 to 400,000',wrong:['From 2,000 to 20,000','From 50,000 to 200,000','From 100,000 to 500,000'],explain:'Freed people flooded into independent Black churches after the war. The AME Church grew twentyfold in a decade — one of the most rapid expansions in American religious history.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'What role did Black churches play during Reconstruction?',correct:'They became organizing centers of Black community life — providing schools, political leadership, and community institutions',wrong:['They focused exclusively on spiritual worship and avoided political engagement','They aligned with Southern white churches to promote racial reconciliation','They were primarily funded by Northern missionary societies with little local leadership'],explain:'Black churches were the institutional backbone of Reconstruction-era Black life — sources of education, political organizing, and community resilience until Jim Crow dismantled many of their gains.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'When did Reconstruction effectively end, leaving Black churches vulnerable to Jim Crow violence?',correct:'1877, when federal troops withdrew from the South',wrong:['1865, when the war ended','1870, when the Fifteenth Amendment was ratified','1900, when segregation laws were fully in place'],explain:'Reconstruction ended in 1877 with the withdrawal of federal troops. The period of Black political and institutional flourishing gave way to the violence and legal structures of Jim Crow.'},
  {type:'tf',era:'Civil War & Reconstruction',q:'Lincoln\'s Second Inaugural Address was delivered in 1865, near the end of the Civil War.',answer:true,explain:'The address was delivered on March 4, 1865 — weeks before Lee\'s surrender at Appomattox and Lincoln\'s assassination.'},
  {type:'tf',era:'Civil War & Reconstruction',q:'After emancipation, freed people generally remained in white-supervised churches.',answer:false,explain:'Freed people overwhelmingly left white-supervised congregations to join or form independent Black Baptist and AME churches — a mass institutional exodus representing Black religious self-determination.'},
  {type:'tf',era:'Civil War & Reconstruction',q:'Lincoln\'s Second Inaugural is considered the greatest theological statement made by an American president.',answer:true,explain:'Its refusal to claim God simply for the Union, and its interpretation of the war as national judgment for slavery, represents a depth of theological reflection unmatched in American political oratory.'},
  {type:'quote',era:'Civil War & Reconstruction',quote:'"Both read the same Bible and pray to the same God, and each invokes His aid against the other."',cite:'— Abraham Lincoln, Second Inaugural Address, March 4, 1865',q:'Lincoln used this observation to argue what about the war\'s divine significance?',correct:'That the war represented God\'s judgment on the national sin of slavery, not God\'s endorsement of either side',wrong:['That both sides were equally righteous before God','That God had no interest in the war\'s outcome','That prayer was ineffective in a time of national sin'],explain:'Rather than claim God for the Union, Lincoln suggested the war was God\'s judgment on the whole nation — North and South — for the shared sin of slavery.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'About how many Americans had the Civil War killed by 1865?',correct:'620,000',wrong:['200,000','1,000,000','400,000','750,000','100,000','50,000'],explain:'By 1865 the Civil War had killed about 620,000 Americans.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'On what date did Lincoln deliver his Second Inaugural Address?',correct:'March 4, 1865',wrong:['April 14, 1865','March 4, 1861','January 1, 1863','November 19, 1863','March 4, 1864','July 4, 1865'],explain:'Lincoln delivered the Second Inaugural on March 4, 1865, five weeks before his assassination.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'By 1870, the AME Church had grown to about how many members?',correct:'400,000',wrong:['20,000','100,000','1,000,000','50,000','250,000','600,000'],explain:'The AME Church grew from 20,000 to 400,000 members in the single decade after the war.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'Reconstruction is generally dated from 1865 to what year?',correct:'1877',wrong:['1865','1870','1883','1890','1900','1865'],explain:'Reconstruction ran from 1865 to 1877; its end left Black churches vulnerable to Jim Crow violence.'},
  {type:'mc',era:'Civil War & Reconstruction',q:'After Reconstruction ended, Black churches faced the violence of what?',correct:'Jim Crow',wrong:['Reconstruction','the Great Migration','Prohibition','the Red Scare','Manifest Destiny','the Gilded Age'],explain:'The end of Reconstruction left Black churches exposed to the violence of the Jim Crow era.'},
]}

export function A20_QUESTIONS(){return[
  {type:'mc',era:'Gilded Age Evangelism',q:'What was Dwight L. Moody\'s occupation before becoming an evangelist?',correct:'A shoe salesman in Chicago',wrong:['A circuit-riding Methodist minister','A newspaper editor in New York','A seminary professor in Boston'],explain:'Moody had no formal theological training; he was a Chicago shoe salesman who converted to Christianity and threw himself into YMCA work and street evangelism.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'What institution did Moody found in Chicago in 1886?',correct:'The Moody Bible Institute',wrong:['Wheaton College','The YMCA Training School','The Chicago Theological Seminary'],explain:'The Moody Bible Institute trained lay evangelists and workers; it became a center of American fundamentalism.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'How did Moody\'s message differ in tone from Finney\'s?',correct:'Moody emphasized a God of love more than a God of judgment',wrong:['Moody rejected emotional appeals entirely','Moody preached hellfire more intensely than Finney','Moody stressed God\'s sovereignty where Finney stressed human choice'],explain:'Moody\'s preaching was warmer and less confrontational than Finney\'s; he stressed God\'s love for sinners rather than the threat of judgment.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'Who was Moody\'s singing partner in the urban crusades?',correct:'Ira Sankey',wrong:['Philip Bliss','Charles Alexander','Homer Rodeheaver'],explain:'Sankey\'s popular gospel music was a key draw of the crusades; the pair transformed how music functioned in mass evangelism.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'In which years did Moody conduct his famous British campaigns?',correct:'1873–1875',wrong:['1865–1867','1880–1882','1860–1862'],explain:'The 1873–75 British campaigns drew enormous crowds and made Moody internationally famous before his American urban crusades.'},
  {type:'tf',era:'Gilded Age Evangelism',q:'Moody had no formal theological training before becoming an evangelist.',answer:true,explain:'He was a shoe salesman who became an evangelist entirely outside the seminary system — consistent with the democratic, lay-driven tradition of American revivalism.'},
  {type:'tf',era:'Gilded Age Evangelism',q:'Moody\'s revival campaigns were limited to American cities.',answer:false,explain:'His 1873–75 British campaigns were enormously successful and made him internationally famous before his American urban crusades.'},
  {type:'tf',era:'Gilded Age Evangelism',q:'Moody founded the Northfield schools in Massachusetts alongside the Moody Bible Institute.',answer:true,explain:'The Northfield schools trained a generation of lay evangelists, alongside the Moody Bible Institute in Chicago, building the institutional network that anchored American fundamentalism.'},
  {type:'tf',era:'Gilded Age Evangelism',q:'Moody pioneered the practice of organizing local churches to follow up on converts after crusades.',answer:true,explain:'Systematic follow-up was one of Moody\'s key innovations — he organized local churches to nurture converts after each campaign, adapting the circuit-revival model to the industrial city.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'In which city did Dwight L. Moody base his ministry and Bible institute?',correct:'Chicago',wrong:['Boston','New York','Philadelphia','Northfield','London','Springfield'],explain:'Moody, a former Chicago shoe salesman, based his ministry there and founded the Moody Bible Institute in 1886.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'In which state did Moody found his Northfield schools?',correct:'Massachusetts',wrong:['Illinois','New York','Connecticut','Ohio','Pennsylvania','Vermont'],explain:'Moody founded the Northfield schools in Massachusetts to train lay workers and evangelists.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'Moody preached a God of what, more than a God of judgment?',correct:'Love',wrong:['Wrath','Justice','Glory','Mercy','Power','Holiness'],explain:'Moody\'s message was warmer than Finney\'s — he preached a God of love more than a God of judgment.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'What was the name for Moody\'s revival format of large halls, choirs, and church follow-up?',correct:'The urban crusade',wrong:['The camp meeting','The protracted meeting','The tent revival','The prophetic conference','The watch night','The class meeting'],explain:'Moody pioneered the modern urban crusade, the format Billy Graham would later inherit.'},
  {type:'mc',era:'Gilded Age Evangelism',q:'Which 20th-century evangelist inherited Moody\'s urban-crusade tradition?',correct:'Billy Graham',wrong:['Aimee Semple McPherson','Billy Sunday','Charles Fuller','Oral Roberts','Bob Jones','Charles Spurgeon'],explain:'The Finney-to-Moody revivalist tradition was carried into the 20th century by Billy Graham.'},
]}

export function A21_QUESTIONS(){return[
  {type:'mc',era:'Social Gospel',q:'Who published Christianity and the Social Crisis in 1907?',correct:'Walter Rauschenbusch',wrong:['Charles Sheldon','Lyman Abbott','Washington Gladden'],explain:'Rauschenbusch\'s 1907 book, written after eleven years ministering in Hell\'s Kitchen, became the defining text of the Social Gospel movement.'},
  {type:'mc',era:'Social Gospel',q:'What did Rauschenbusch mean by "social sin"?',correct:'Sin embedded in unjust social institutions, not only in individual moral failures',wrong:['The sin of clergy who entered politics','The sin of Catholics attending Protestant services','The personal sins of immoral individuals in society'],explain:'Rauschenbusch argued the church had focused too narrowly on individual sin while ignoring sinful social structures like exploitative labor and poverty.'},
  {type:'mc',era:'Social Gospel',q:'What organization did the Social Gospel movement help produce in 1908?',correct:'The Federal Council of Churches',wrong:['The American Baptist Mission Society','The Moody Bible Institute','The National Council of Catholic Bishops'],explain:'The Federal Council of Churches (1908) united mainline Protestant denominations for cooperative action on social issues.'},
  {type:'mc',era:'Social Gospel',q:'In which New York neighborhood did Rauschenbusch minister for eleven years?',correct:'Hell\'s Kitchen',wrong:['The Bowery','Harlem','Five Points'],explain:'His experience with urban poverty and immigrant squalor in Hell\'s Kitchen shaped his conviction that the church had to address social injustice, not only personal salvation.'},
  {type:'mc',era:'Social Gospel',q:'What was Washington Gladden\'s religious denomination?',correct:'Congregationalist',wrong:['Methodist','Baptist','Presbyterian'],explain:'Gladden was a Congregational minister who was among the first prominent clergy to defend workers\' rights to organize in the 1880s.'},
  {type:'tf',era:'Social Gospel',q:'Washington Gladden defended workers\' rights to organize in the 1880s.',answer:true,explain:'Gladden was among the first prominent ministers to support labor unions, arguing from a Christian perspective that workers had a right to organize.'},
  {type:'tf',era:'Social Gospel',q:'The Social Gospel was universally welcomed across American Protestantism.',answer:false,explain:'Conservatives accused it of reducing the gospel to social work and neglecting personal conversion — a tension that foreshadowed the fundamentalist-modernist controversy.'},
  {type:'tf',era:'Social Gospel',q:'The Social Gospel had long-term influence on the New Deal and Civil Rights Movement.',answer:true,explain:'The Social Gospel\'s emphasis on structural justice planted seeds that flowered in both the New Deal policy agenda and the theological foundations of the Civil Rights Movement.'},
  {type:'mc',era:'Social Gospel',q:'What was the title of Walter Rauschenbusch\'s 1907 defining Social Gospel book?',correct:'Christianity and the Social Crisis',wrong:['Christianity and Liberalism','Applied Christianity','The Social Principles of Jesus','Our Country','In His Steps','The Gospel of Wealth'],explain:'Christianity and the Social Crisis (1907) was the defining text of the Social Gospel movement.'},
  {type:'mc',era:'Social Gospel',q:'To which denomination did Washington Gladden belong?',correct:'Congregational',wrong:['Baptist','Presbyterian','Methodist','Episcopal','Lutheran','Quaker'],explain:'Washington Gladden, a Congregational minister, defended workers\' rights to organize in the 1880s.'},
  {type:'mc',era:'Social Gospel',q:'The Social Gospel planted seeds that later flowered in the New Deal and which movement?',correct:'The Civil Rights Movement',wrong:['The Reformation','The Great Awakening','Prohibition','The Pentecostal movement','The Religious Right','The abolition movement'],explain:'The Social Gospel influenced the New Deal and the Civil Rights Movement a generation later.'},
  {type:'mc',era:'Social Gospel',q:'How many years did Rauschenbusch minister in Hell\'s Kitchen?',correct:'Eleven',wrong:['Five','Twenty','Three','Fifteen','Thirty','Eight'],explain:'Rauschenbusch ministered for eleven years in New York\'s Hell\'s Kitchen before writing his great book.'},
  {type:'mc',era:'Social Gospel',q:'Industrialization packed immigrants into crowded urban what?',correct:'Tenements',wrong:['Factories','Ghettos','Parishes','Missions','Boroughs','Wards'],explain:'As industrialization concentrated wealth, immigrants were packed into urban tenements — the setting of the Social Gospel.'},
]}

export function A22_QUESTIONS(){return[
  {type:'mc',era:'Pentecostalism',q:'Who led the Azusa Street revival?',correct:'William J. Seymour',wrong:['Charles Price','Charles Parham','Aimee Semple McPherson'],explain:'Seymour, a one-eyed Black preacher from Louisiana, led the Azusa Street Mission. His interracial congregation was remarkable in the segregated America of 1906.'},
  {type:'mc',era:'Pentecostalism',q:'What is Pentecostalism\'s defining doctrine?',correct:'That Spirit baptism is evidenced by speaking in tongues',wrong:['That water baptism must be by immersion','That healing always follows genuine faith','That the Second Coming is imminent'],explain:'Charles Parham first connected tongues-speaking with Spirit baptism in 1901; Seymour carried this doctrine to Azusa Street.'},
  {type:'mc',era:'Pentecostalism',q:'Where was the Azusa Street Mission located?',correct:'Los Angeles, California',wrong:['Birmingham, Alabama','Kansas City, Missouri','Chicago, Illinois'],explain:'The Mission operated in an abandoned stable at 312 Azusa Street in Los Angeles from 1906 to 1909.'},
  {type:'mc',era:'Pentecostalism',q:'Who first connected tongues-speaking with Spirit baptism in 1901?',correct:'Charles Parham',wrong:['William Seymour','Aimee Semple McPherson','John Alexander Dowie'],explain:'Parham, a white Holiness preacher in Kansas, first made the theological connection between speaking in tongues and Spirit baptism in 1901 — five years before Azusa Street.'},
  {type:'mc',era:'Pentecostalism',q:'Approximately how many Christians worldwide identify as Pentecostal or charismatic today?',correct:'Over 600 million',wrong:['About 50 million','About 200 million','About 100 million'],explain:'Beginning at Azusa Street in 1906, Pentecostalism became the fastest-growing segment of global Christianity — now over 600 million adherents globally.'},
  {type:'tf',era:'Pentecostalism',q:'The Azusa Street revival was racially integrated in an era of rigid segregation.',answer:true,explain:'Seymour\'s mission drew white, Black, and Hispanic worshipers together — a remarkable fact in 1906 America.'},
  {type:'tf',era:'Pentecostalism',q:'Pentecostalism has remained primarily an American phenomenon.',answer:false,explain:'Azusa Street sent missionaries worldwide; Pentecostalism now represents over 600 million Christians globally and is strongest in the global South.'},
  {type:'tf',era:'Pentecostalism',q:'Seymour learned his theology of Spirit baptism directly from Charles Parham.',answer:true,explain:'Seymour studied under Parham in Houston before traveling to Los Angeles, bringing Parham\'s doctrine of tongues as the evidence of Spirit baptism to the Azusa Street mission.'},
  {type:'quote',era:'Pentecostalism',quote:'"The color line was washed away in the blood."',cite:'— Frank Bartleman, eyewitness at Azusa Street Mission, 1906',q:'What did this description of the Azusa Street revival emphasize?',correct:'Its unusual racial integration across the color line in a deeply segregated era',wrong:['Its emphasis on healing from physical sickness','Its connection to the earlier Holiness movement','Its rejection of formal church structures'],explain:'Eyewitnesses noted that the races worshiped together at Azusa Street — a social miracle in 1906 America — before the revival\'s racial unity fragmented as Pentecostalism spread into segregated denominations.'},
  {type:'mc',era:'Pentecostalism',q:'On which street did the prayer group first speak in tongues before moving to Azusa Street?',correct:'Bonnie Brae Street',wrong:['Pearl Street','Beale Street','Main Street','Spring Street','Bourbon Street','Bethel Street'],explain:'The revival began at a house on Bonnie Brae Street before moving to 312 Azusa Street.'},
  {type:'mc',era:'Pentecostalism',q:'From which state did Azusa Street leader William J. Seymour come?',correct:'Louisiana',wrong:['Kansas','Texas','California','Mississippi','Tennessee','Georgia'],explain:'William J. Seymour was a soft-spoken Black preacher from Louisiana.'},
  {type:'mc',era:'Pentecostalism',q:'In which state did Charles Parham first connect tongues with Spirit baptism in 1901?',correct:'Kansas',wrong:['California','Louisiana','Texas','Missouri','Tennessee','Oklahoma'],explain:'Charles Parham first linked tongues-speaking with Spirit baptism in Topeka, Kansas, in 1901.'},
  {type:'mc',era:'Pentecostalism',q:'On what date in 1906 did the Bonnie Brae group begin speaking in tongues?',correct:'April 9, 1906',wrong:['April 18, 1906','January 1, 1901','April 9, 1901','July 8, 1906','December 25, 1906','April 9, 1909'],explain:'On April 9, 1906, the prayer group began speaking in tongues, launching the Azusa Street revival.'},
  {type:'mc',era:'Pentecostalism',q:'Charles Parham, who taught Seymour, was a preacher of which tradition?',correct:'Holiness',wrong:['Baptist','Methodist','Presbyterian','Reformed','Lutheran','Adventist'],explain:'Parham was a white Holiness preacher who connected tongues-speaking with the baptism of the Holy Spirit.'},
]}

export function A23_QUESTIONS(){return[
  {type:'mc',era:'Fundamentalism',q:'Who funded the publication of The Fundamentals (1910–1915)?',correct:'Two wealthy California oilmen',wrong:['The Presbyterian General Assembly','The Southern Baptist Convention','The Moody Bible Institute'],explain:'Lyman and Milton Stewart, founders of Union Oil Company, funded the printing and distribution of the ninety essays to every pastor, missionary, and theology student in America.'},
  {type:'mc',era:'Fundamentalism',q:'Who coined the term "fundamentalist" in 1920?',correct:'Baptist editor Curtis Lee Laws',wrong:['Charles Hodge','Harry Emerson Fosdick','H. L. Mencken'],explain:'Laws used the term in the Watchman-Examiner to describe those willing to do "battle royal" for the fundamentals of the faith.'},
  {type:'mc',era:'Fundamentalism',q:'Which of the following was among the core doctrines defended in The Fundamentals?',correct:'The inerrancy of Scripture and the virgin birth',wrong:['The compatibility of evolution and Genesis','The Social Gospel and workers\' rights','The ordination of women'],explain:'The Fundamentals defended the virgin birth, physical resurrection, inerrancy of Scripture, substitutionary atonement, and literal Second Coming.'},
  {type:'mc',era:'Fundamentalism',q:'How many essays were collected in The Fundamentals?',correct:'Ninety',wrong:['Twelve','Fifty','One hundred and twenty'],explain:'Ninety essays were published between 1910 and 1915, covering core Protestant doctrines under attack from higher criticism, Darwinism, and liberal theology.'},
  {type:'mc',era:'Fundamentalism',q:'What three developments most alarmed conservative Protestants by 1910?',correct:'Higher biblical criticism, Darwinian evolution, and the Social Gospel',wrong:['Catholicism, Mormonism, and the Social Gospel','Pentecostalism, liberalism, and evolution','Catholic immigration, temperance activism, and biblical criticism'],explain:'Higher criticism in the seminaries, Darwin\'s challenge to Genesis, and the Social Gospel\'s apparent substitution of social reform for personal salvation all combined to alarm conservative Protestants.'},
  {type:'tf',era:'Fundamentalism',q:'The Fundamentals were distributed free of charge to clergy and theology students.',answer:true,explain:'The Stewart brothers paid for all ninety essays to be printed and mailed free to every pastor, missionary, and theology student in the English-speaking world.'},
  {type:'tf',era:'Fundamentalism',q:'The term "fundamentalist" was coined by a skeptic to mock conservatives.',answer:false,explain:'It was coined by the Baptist editor Curtis Lee Laws in 1920 as a positive self-description of those ready to fight for core doctrines.'},
  {type:'tf',era:'Fundamentalism',q:'The fundamentalist movement had a network of Bible institutes and summer conferences before the 1920s controversy.',answer:true,explain:'Moody, Dallas, and Philadelphia Bible institutes, plus a summer conference circuit and growing press, meant fundamentalism was organized and ready for the coming denominational battles.'},
  {type:'mc',era:'Fundamentalism',q:'Over which years was the essay series The Fundamentals published?',correct:'1910–1915',wrong:['1900–1905','1920–1925','1915–1920','1895–1900','1906–1909','1925–1930'],explain:'The Fundamentals — ninety essays — were published and mailed free between 1910 and 1915.'},
  {type:'mc',era:'Fundamentalism',q:'The California oilmen who funded The Fundamentals were the ___ brothers.',correct:'Stewart',wrong:['Rockefeller','Tappan','Pew','Getty','Hearst','Crocker'],explain:'Lyman and Milton Stewart funded the free publication of The Fundamentals.'},
  {type:'mc',era:'Fundamentalism',q:'Curtis Lee Laws, who coined "fundamentalist," edited a paper of which denomination?',correct:'Baptist',wrong:['Presbyterian','Methodist','Episcopal','Lutheran','Congregational','Pentecostal'],explain:'Baptist editor Curtis Lee Laws coined "fundamentalist" in 1920 for those ready to do "battle royal" for the faith.'},
  {type:'mc',era:'Fundamentalism',q:'What was the name for treating the Bible as a historical document subject to scholarly analysis?',correct:'Higher criticism',wrong:['Lower criticism','Source theory','Form criticism','Redaction','Textual criticism','Hermeneutics'],explain:'Higher biblical criticism, entering the seminaries, was a chief target of conservative Protestants.'},
  {type:'mc',era:'Fundamentalism',q:'Besides the virgin birth, resurrection, and inerrancy, The Fundamentals defended the literal what?',correct:'Second Coming',wrong:['Atonement','Trinity','Incarnation','Ascension','Millennium','Rapture'],explain:'The essays defended the virgin birth, physical resurrection, inerrancy of Scripture, and literal Second Coming.'},
]}

export function A24_QUESTIONS(){return[
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'What was the title of Fosdick\'s 1922 sermon that crystallized the controversy?',correct:'"Shall the Fundamentalists Win?"',wrong:['"The Perils of Modernism"','"A Living Faith for Modern Man"','"Christianity and Culture"'],explain:'Fosdick\'s sermon at First Presbyterian Church in New York was a direct challenge to fundamentalist influence in mainline denominations.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'What was J. Gresham Machen\'s central argument in Christianity and Liberalism (1923)?',correct:'That liberalism was not a revised Christianity but an entirely different religion',wrong:['That fundamentalists should separate from all liberal denominations immediately','That evolution was compatible with orthodox Christianity','That the Social Gospel was the true expression of Christian faith'],explain:'Machen argued liberal theology had abandoned the historic gospel of redemption and replaced it with a gospel of human moral improvement — making it a different religion, not a variant of Christianity.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'What institution did Machen found after being forced out of Princeton?',correct:'Westminster Theological Seminary',wrong:['Gordon-Conwell Seminary','Dallas Theological Seminary','Moody Bible Institute'],explain:'Machen founded Westminster in 1929 in Philadelphia as a confessionally Reformed alternative to Princeton after it moved in a more moderate direction.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'What was Harry Emerson Fosdick\'s actual denominational affiliation?',correct:'Baptist',wrong:['Presbyterian','Methodist','Congregationalist'],explain:'Fosdick was a Baptist, but was serving as a guest preacher at First Presbyterian Church in New York when he delivered the controversial 1922 sermon.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'Machen argued liberals had replaced the gospel of redemption with what?',correct:'A gospel of human moral improvement',wrong:['A gospel of social revolution','A gospel of intellectual freedom','A gospel of scientific progress'],explain:'Machen\'s precise argument was that liberal theology substituted ethics for salvation — replacing a faith about what God had done in Christ with a faith about human moral progress.'},
  {type:'tf',era:'Fundamentalist-Modernist Controversy',q:'Harry Emerson Fosdick was a Presbyterian minister.',answer:false,explain:'Fosdick was a Baptist, but was serving as a guest preacher at First Presbyterian Church in New York when he delivered the controversial 1922 sermon.'},
  {type:'tf',era:'Fundamentalist-Modernist Controversy',q:'Machen argued liberalism was simply a more modern form of Christianity.',answer:false,explain:'Machen argued the opposite: that liberalism had abandoned the historic gospel entirely and was a different religion, not a revised form of Christianity.'},
  {type:'quote',era:'Fundamentalist-Modernist Controversy',quote:'"In the sphere of religion…liberalism is not a religion within Christianity at all, but a different religion altogether."',cite:'— J. Gresham Machen, Christianity and Liberalism, 1923',q:'What had liberals replaced the gospel of redemption with, according to Machen?',correct:'A gospel of human moral improvement',wrong:['Scripture with tradition','Personal faith with social action','Orthodox theology with biblical criticism'],explain:'Machen\'s argument was precise: the two systems were not competing variants but distinct religions with different objects of faith.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'In what year did Fosdick preach "Shall the Fundamentalists Win?"',correct:'1922',wrong:['1920','1923','1925','1929','1910','1915'],explain:'Harry Emerson Fosdick preached "Shall the Fundamentalists Win?" in 1922.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'At which New York church was Fosdick preaching when he gave the sermon?',correct:'First Presbyterian Church',wrong:['Riverside Church','First Baptist Church','Marble Collegiate Church','Trinity Church','Brick Presbyterian Church','Old First Church'],explain:'Fosdick, a liberal Baptist, was preaching at First Presbyterian Church in New York.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'At which seminary did J. Gresham Machen teach before founding Westminster?',correct:'Princeton',wrong:['Union','Yale','Westminster','Dallas','Fuller','Gordon'],explain:'Machen was a Princeton theologian until he was forced out and founded Westminster in 1929.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'In what year did Machen found Westminster Theological Seminary?',correct:'1929',wrong:['1923','1922','1925','1930','1935','1920'],explain:'Machen founded Westminster Theological Seminary in 1929 after leaving Princeton.'},
  {type:'mc',era:'Fundamentalist-Modernist Controversy',q:'To which denomination did Harry Emerson Fosdick actually belong?',correct:'Baptist',wrong:['Presbyterian','Methodist','Episcopal','Congregational','Lutheran','Quaker'],explain:'Fosdick was a liberal Baptist, though he was preaching at a Presbyterian church when controversy erupted.'},
]}

export function A25_QUESTIONS(){return[
  {type:'mc',era:'The Scopes Trial',q:'What law did John Scopes violate in the 1925 trial?',correct:'The Butler Act, which made it illegal to teach human evolution in Tennessee public schools',wrong:['A law mandating Bible reading in public schools','A law banning the distribution of anti-religious literature','A law requiring prayer in public schools'],explain:'The Butler Act (1925) made it illegal to teach any theory that denied the divine creation of man as taught in the Bible.'},
  {type:'mc',era:'The Scopes Trial',q:'Who cross-examined William Jennings Bryan on his literal reading of Genesis?',correct:'Clarence Darrow',wrong:['H. L. Mencken','John Scopes','Amos Butler'],explain:'Darrow\'s cross-examination of Bryan on the stand — treating the great populist as a witness rather than a hero — became one of the most famous courtroom scenes in American history.'},
  {type:'mc',era:'The Scopes Trial',q:'What was the broader consequence of the Scopes Trial for fundamentalism?',correct:'Fundamentalists won legally but lost public opinion, and many withdrew to build a separate subculture',wrong:['Fundamentalism collapsed entirely after the trial','Fundamentalism gained new respectability in the mainline denominations','Evolution was banned from all American public schools'],explain:'Despite Scopes\'s conviction, press coverage — especially Mencken\'s dispatches — made fundamentalists look like ignorant rurals. Many withdrew to build Bible institutes, radio programs, and their own institutions.'},
  {type:'mc',era:'The Scopes Trial',q:'What happened to William Jennings Bryan after the Scopes Trial?',correct:'He died five days after the trial ended',wrong:['He was elected governor of Tennessee','He founded the American Anti-Evolution League','He published a book defending the Butler Act'],explain:'Bryan died in his sleep in Dayton, Tennessee, on July 26, 1925 — five days after the trial ended.'},
  {type:'mc',era:'The Scopes Trial',q:'When did fundamentalists broadly re-engage the American public square after their post-Scopes withdrawal?',correct:'In the 1970s',wrong:['In the 1930s','In the 1950s','In the 1990s'],explain:'Fundamentalists withdrew to build a parallel subculture for roughly two decades. Their re-engagement began with the rise of the Religious Right in the 1970s, culminating in Jerry Falwell\'s Moral Majority (1979).'},
  {type:'tf',era:'The Scopes Trial',q:'John Scopes was acquitted at the Scopes Trial.',answer:false,explain:'Scopes was convicted and fined one hundred dollars, though the verdict was later overturned on a technicality.'},
  {type:'tf',era:'The Scopes Trial',q:'H. L. Mencken\'s press coverage of the trial was sympathetic to the fundamentalists.',answer:false,explain:'Mencken\'s dispatches from Dayton were viciously mocking, portraying fundamentalists as ignorant rurals. His coverage shaped the national perception of the trial.'},
  {type:'tf',era:'The Scopes Trial',q:'The fundamentalist withdrawal after Scopes included building Bible institutes, radio programs, and independent mission agencies.',answer:true,explain:'Having lost the culture war of public opinion, fundamentalists retreated to build a parallel subculture — a separate institutional world that kept conservative Christianity alive while disengaging from mainstream public life.'},
  {type:'mc',era:'The Scopes Trial',q:'What was the name of the 1925 Tennessee law banning the teaching of evolution?',correct:'The Butler Act',wrong:['The Scopes Act','The Volstead Act','The Comstock Act','The Genesis Act','The Darrow Act','The Dayton Act'],explain:'Tennessee\'s Butler Act (1925) made it illegal to teach human evolution in public schools.'},
  {type:'mc',era:'The Scopes Trial',q:'In what town was the Scopes Trial held?',correct:'Dayton, Tennessee',wrong:['Nashville, Tennessee','Memphis, Tennessee','Knoxville, Tennessee','Chattanooga, Tennessee','Clinton, Tennessee','Athens, Tennessee'],explain:'The Scopes Trial took place in Dayton, Tennessee, in 1925.'},
  {type:'mc',era:'The Scopes Trial',q:'Who argued for the prosecution at the Scopes Trial?',correct:'William Jennings Bryan',wrong:['Clarence Darrow','H. L. Mencken','John Scopes','Curtis Lee Laws','J. Gresham Machen','Harry Emerson Fosdick'],explain:'William Jennings Bryan, the three-time presidential candidate, argued for the prosecution; he died five days after the trial.'},
  {type:'mc',era:'The Scopes Trial',q:'Scopes was convicted and fined how much?',correct:'One hundred dollars',wrong:['One thousand dollars','Ten dollars','Five hundred dollars','Fifty dollars','Nothing','One dollar'],explain:'Scopes was convicted and fined one hundred dollars.'},
  {type:'mc',era:'The Scopes Trial',q:'In what year was the Scopes Trial held?',correct:'1925',wrong:['1920','1923','1929','1919','1927','1930'],explain:'The Scopes "Monkey Trial" was held in 1925 in Dayton, Tennessee.'},
]}

export function A26_QUESTIONS(){return[
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'What event convinced Karl Barth to reject liberal theology?',correct:'His liberal theology professors signing a manifesto supporting the Kaiser\'s war in World War I',wrong:['The Russian Revolution','The Scopes Trial in America','The failure of the Social Gospel to end poverty'],explain:'Barth watched his liberal theology teachers sign the war manifesto and concluded liberal theology had made God the servant of human culture rather than its judge.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'What was Reinhold Niebuhr\'s "Christian Realism"?',correct:'A theology rooted in original sin, arguing that groups inevitably pursue self-interest and power must check power',wrong:['A call to return to fundamentalist doctrine','An argument that individual Christians should withdraw from politics','A defense of American democracy as divinely ordained'],explain:'Niebuhr applied the doctrine of original sin to politics, arguing that nations, classes, and races inevitably serve their own interests — making idealism about group behavior naive.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'What did Niebuhr publish in 1932 that defined Christian Realism?',correct:'Moral Man and Immoral Society',wrong:['The Nature and Destiny of Man','The Children of Light and the Children of Darkness','Christianity and Power Politics'],explain:'Moral Man and Immoral Society argued that individuals could act morally but groups inevitably served their own interests — a direct critique of the Social Gospel\'s optimism.'},
  {type:'tf',era:'Neo-Orthodoxy & Christian Realism',q:'Karl Barth\'s neo-orthodoxy recovered the idea of God\'s radical transcendence over human culture.',answer:true,explain:'Barth argued God could not be identified with any human culture, nation, or ideology — a direct rebuke to liberal theology\'s accommodation of German nationalism.'},
  {type:'tf',era:'Neo-Orthodoxy & Christian Realism',q:'Reinhold Niebuhr argued that nations and groups could be reformed by idealism and education.',answer:false,explain:'Niebuhr\'s whole point was the opposite — that groups inevitably pursue self-interest, and power must be checked by power, not by moral persuasion alone.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'Karl Barth was a Reformed pastor of which nationality?',correct:'Swiss',wrong:['German','American','Dutch','Scottish','French','English'],explain:'Karl Barth was a Swiss Reformed pastor whose 1919 Romans commentary broke with liberal theology.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'Barth\'s influential 1919 commentary was written on which book of the Bible?',correct:'Romans',wrong:['Galatians','John','Genesis','Hebrews','Revelation','Isaiah'],explain:'Barth\'s 1919 commentary on Romans recovered God\'s radical transcendence against liberal accommodation.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'What did Reinhold Niebuhr call his political theology?',correct:'Christian Realism',wrong:['The Social Gospel','Neo-orthodoxy','Liberalism','Dispensationalism','Postmillennialism','Personalism'],explain:'Niebuhr\'s "Christian Realism" drew on original sin to argue that power must be checked by power.'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'Which doctrine did Niebuhr draw on to argue that groups serve their own interests?',correct:'Original sin',wrong:['Predestination','Justification','Incarnation','The Trinity','Providence','Election'],explain:'Niebuhr applied the doctrine of original sin to politics in Moral Man and Immoral Society (1932).'},
  {type:'mc',era:'Neo-Orthodoxy & Christian Realism',q:'In what year did Barth publish his Romans commentary?',correct:'1919',wrong:['1932','1914','1925','1945','1907','1960'],explain:'Barth published his Romans commentary in 1919, after World War I shattered liberal optimism.'},
]}

