export function A32_QUESTIONS(){return[
  {type:'mc',era:'The Bible Wars',q:'What was the Chicago Statement on Biblical Inerrancy?',correct:'A 1978 document signed by over 300 evangelical scholars precisely defining Scripture as without error in all that it affirms',wrong:['A 1978 Supreme Court ruling on Bible reading in public schools','A manifesto by the Jesus Seminar rejecting traditional views of Scripture','A statement by mainline denominations accepting higher biblical criticism'],explain:'The Chicago Statement was produced at a summit of evangelical scholars in 1978, offering a careful definition of inerrancy in response to drift in evangelical institutions like Fuller Seminary.'},
  {type:'mc',era:'The Bible Wars',q:'What method did the Jesus Seminar use to evaluate the sayings of Jesus?',correct:'Voting with colored beads — red for authentic, black for inauthentic',wrong:['A panel of bishops voting by secret ballot','Computer analysis of the Greek text','A consensus statement signed after debate'],explain:'The bead-voting system — red, pink, gray, or black — was designed to produce quantifiable results and generate media attention. Critics called it theatrics; supporters called it democratic scholarship.'},
  {type:'mc',era:'The Bible Wars',q:'What did the Jesus Seminar conclude about the sayings attributed to Jesus in the gospels?',correct:'That only about 18% were likely authentic',wrong:['That all four gospels were equally reliable','That Jesus never existed as a historical figure','That the Gospel of John was the most historically accurate'],explain:'The Seminar\'s skeptical conclusions about the gospels\' historicity received enormous mainstream media coverage and forced evangelicals to defend publicly their trust in Scripture.'},
  {type:'mc',era:'The Bible Wars',q:'The Chicago Statement\'s definition of inerrancy applied to Scripture in what form?',correct:'The original manuscripts — inerrancy applied to the autographs, not all copies',wrong:['All existing translations including the King James Version','Only the New Testament, not the Old','Only passages directly quoted by Jesus'],explain:'The Statement specified inerrancy applied to Scripture\'s original manuscripts (autographs). Critics noted no original manuscripts survive; defenders said the definition was still meaningful as a claim about the nature of inspiration.'},
  {type:'tf',era:'The Bible Wars',q:'Fuller Theological Seminary remained committed to strict inerrancy throughout the 1960s and 1970s.',answer:false,explain:'Fuller quietly moved away from strict inerrancy in this period, which was one of the direct triggers for the Chicago Statement in 1978.'},
  {type:'tf',era:'The Bible Wars',q:'The Jesus Seminar was primarily aimed at an academic audience of scholars.',answer:false,explain:'The Seminar was deliberately designed to reach a popular audience — its conclusions were publicized in mainstream media including Newsweek and Time, not just academic journals.'},
  {type:'tf',era:'The Bible Wars',q:'The Southern Baptist Convention\'s conservative resurgence of 1979 was connected to the inerrancy debate.',answer:true,explain:'The SBC conservatives who began taking control of the denomination in 1979 made inerrancy a defining issue, eventually requiring it of all SBC seminary faculty.'},
  {type:'quote',era:'The Bible Wars',quote:'"Being wholly and verbally God-given, Scripture is without error or fault in all its teaching, no less in what it states about God\'s acts in creation, about the events of world history, and about its own literary origins."',cite:'— Chicago Statement on Biblical Inerrancy, Article XII, 1978',q:'The Chicago Statement\'s definition of inerrancy extended to which domains?',correct:'All that Scripture affirms — including history, creation, and literary origins, not only faith and practice',wrong:['Only passages confirmed by archaeological evidence','Only the words of Jesus in the four gospels','Only matters of salvation and Christian living'],explain:'The breadth of the Chicago Statement\'s inerrancy claim — extending to history and science, not just doctrine — was precisely what made it controversial and what the Jesus Seminar implicitly challenged.'},
  {type:'mc',era:'The Bible Wars',q:'Who founded the Jesus Seminar in 1985?',correct:'Robert Funk',wrong:['John Dominic Crossan','Marcus Borg','Bart Ehrman','N.T. Wright','Rudolf Bultmann','Albert Schweitzer'],explain:'Funk, a New Testament scholar, wanted to reach a popular audience rather than just academic journals — and built the bead-voting system to generate media attention.'},
  {type:'mc',era:'The Bible Wars',q:'In which year did the Southern Baptist Convention\'s "conservative resurgence" begin?',correct:'1979',wrong:['1962','1973','1978','1985','1990','1995'],explain:'The 1979 SBC presidential election began a multi-decade campaign by conservatives to require inerrancy of all denominational seminary faculty.'},
]}

