export function A_FINAL_QUESTIONS(){return[
  {type:'mc',era:'Colonial',q:'What most clearly distinguished the Plymouth Pilgrims from the Massachusetts Bay Puritans?',correct:'The Pilgrims were Separatists who had broken from the Church of England; the Bay Puritans were non-Separatists who hoped to purify it from within',wrong:['The Pilgrims were Anglican; the Bay Puritans were Presbyterian','The Pilgrims came primarily for trade; the Bay Puritans came primarily for religion','The Pilgrims came in 1630; the Bay Puritans came a decade earlier in 1620'],explain:'The Plymouth founders had separated from the Church of England and lived in Leiden before sailing in 1620. Winthrop\'s 1630 Bay Puritans remained technically within the Church of England while seeking its reform.'},

  {type:'timeline',era:'Colonial',q:'Place these colonial milestones in chronological order.',events:[
    {label:'Jamestown founded; Church of England arrives in Virginia',year:1607},
    {label:'Pilgrims sign the Mayflower Compact at Plymouth',year:1620},
    {label:'Winthrop leads the Great Migration to Massachusetts Bay',year:1630},
    {label:'Maryland passes the Act Concerning Religion',year:1649},
    {label:'Half-Way Covenant adopted by the Massachusetts Synod',year:1662},
  ],explain:'These five events trace the arc of the colonial church from Anglican Virginia to Puritan New England — and to the first signs of Puritan decline.'},

  {type:'mc',era:'Colonial',q:'Roger Williams was banished from Massachusetts in 1636 chiefly because he argued that —',correct:'Civil magistrates had no authority over religious conscience',wrong:['Infants should not be baptized','The Church of England was a true church','Property in the colony should be held in common'],explain:'Williams was convicted of sedition and heresy after teaching that the civil government had no jurisdiction over the soul and that the king\'s charter could not grant Indian land without purchase.'},

  {type:'mc',era:'Colonial',q:'The 1649 Maryland Act Concerning Religion granted free exercise of religion to —',correct:'All Trinitarian Christians',wrong:['All inhabitants regardless of religion','Catholics and Anglicans only','Anyone except open atheists'],explain:'Maryland\'s 1649 Act was the first religious toleration law in the English colonies, but it protected only Trinitarian Christians and sentenced to death anyone who denied the Trinity.'},

  {type:'quote',era:'Colonial',quote:'"For we must consider that we shall be as a city upon a hill. The eyes of all people are upon us."',cite:'— John Winthrop, "A Model of Christian Charity," c. 1630',q:'What was Winthrop\'s central theological claim in this passage?',correct:'That Massachusetts Bay was a covenanted community whose success or failure would be visible to God and the watching world',wrong:['That the colony would become the capital of a new Christian empire','That God had guaranteed the colony\'s military victory','That New Englanders were spiritually superior to other colonists'],explain:'Winthrop drew on Matthew 5:14 to frame the colony as a covenant before God — a venture whose failure would shame God\'s cause among the nations.'},

  {type:'mc',era:'Colonial',q:'What problem did the Half-Way Covenant of 1662 attempt to solve, and what was its compromise?',correct:'Declining conversions among the children of original "visible saints" — it baptized grandchildren without granting them the Lord\'s Supper or a vote in church affairs',wrong:['A bishop dispute — it allowed Congregational ministers to ordain without episcopal approval','Tax resistance — it cut the parish rate in half for partial members','A doctrinal dispute over predestination — it permitted both Arminian and Calvinist preaching'],explain:'As first-generation members aged, their descendants often could not give a conversion narrative. The Half-Way Covenant extended baptism — but explicitly withheld communion and church voting — to such partial members.'},

  {type:'mc',era:'First Awakening',q:'Jonathan Edwards\'s 1734–35 town-wide revival, recorded in A Faithful Narrative of the Surprising Work of God, took place in what town?',correct:'Northampton, Massachusetts',wrong:['Enfield, Connecticut','New Haven, Connecticut','Boston, Massachusetts'],explain:'The Northampton awakening of 1734–35 — and Edwards\'s widely-read narrative of it (1737) — gave the larger movement of the 1740s its name and template.'},

  {type:'mc',era:'First Awakening',q:'Theodorus Frelinghuysen, the New Jersey revivalist often called the first stirring of the Great Awakening, was a minister in which denomination?',correct:'Dutch Reformed',wrong:['Anglican','Presbyterian','Baptist'],explain:'Frelinghuysen was a Dutch Reformed pietist whose insistence on conversion as a prerequisite for communion stirred revival in the Raritan Valley beginning in the 1720s.'},

  {type:'mc',era:'First Awakening',q:'What lasting schism resulted from the First Great Awakening among American Presbyterians?',correct:'The 1741 split between Old Side and New Side, which lasted seventeen years',wrong:['The split between the Synod of Philadelphia and the Synod of Charleston','The withdrawal of Scottish Covenanters into the Reformed Presbyterian Church','The merger of Congregationalists and Presbyterians under the Plan of Union'],explain:'The colonial Presbyterian Synod divided in 1741 over the revival\'s methods and Gilbert Tennent\'s 1740 sermon "The Danger of an Unconverted Ministry." Old and New Side remained separate for seventeen years.'},

  {type:'mc',era:'First Awakening',q:'Which four colleges were the First Awakening\'s most durable institutional legacy?',correct:'Princeton (1746), Brown (1764), Rutgers (1766), and Dartmouth (1769)',wrong:['Harvard, Yale, William & Mary, and King\'s College','Williams, Amherst, Bowdoin, and Wesleyan','Andover, Union, Princeton Seminary, and Westminster'],explain:'New Light and New Side parties founded these four colleges to train revival-friendly ministers — the Awakening\'s most durable institutional fruit.'},

  {type:'mc',era:'Revolution',q:'The British called New England\'s patriot clergy the "Black Regiment." Who were they?',correct:'Congregational and Presbyterian preachers, named for their black preaching robes',wrong:['African American chaplains attached to Continental Army units','A clandestine network of Baptist itinerants in the Carolina backcountry','Anglican clergy who secretly broke their ordination oaths to support the patriots'],explain:'Patriot Congregational and Presbyterian preachers — in their black robes — framed the revolutionary cause in religious terms. Most Anglican clergy, bound by ordination oaths to the king, remained loyalists.'},

  {type:'mc',era:'Founding',q:'Whose 1785 "Memorial and Remonstrance" argued powerfully against state support for religion in Virginia?',correct:'James Madison',wrong:['Thomas Jefferson','Patrick Henry','George Mason'],explain:'Madison\'s "Memorial and Remonstrance" (1785) prepared the way for the passage of Jefferson\'s Virginia Statute for Religious Freedom the following year.'},

  {type:'mc',era:'Founding',q:'Which state was the last to disestablish its official church?',correct:'Massachusetts, in 1833',wrong:['Connecticut, in 1818','Virginia, in 1786','New Hampshire, in 1819'],explain:'Several states kept religious establishments after the First Amendment, which applied only to the federal government. Massachusetts was the last to disestablish, holding out until 1833.'},

  {type:'mc',era:'Second Awakening',q:'The 1801 Cane Ridge camp meeting, the largest of the Second Great Awakening, took place in what state?',correct:'Kentucky',wrong:['Tennessee','Virginia','Ohio'],explain:'An estimated 10,000–20,000 gathered at Cane Ridge, Kentucky, in 1801 — a defining moment of frontier revivalism and the camp meeting form.'},

  {type:'mc',era:'Second Awakening',q:'Who organized the Methodist circuit-riding system that reached scattered frontier settlers?',correct:'Bishop Francis Asbury',wrong:['Bishop Thomas Coke','Peter Cartwright','Lorenzo Dow'],explain:'Asbury organized the endless loops of Methodist circuit riders. Combined with the Baptist farmer-preacher, this low-cost, high-mobility model made Methodists and Baptists the two largest Protestant bodies in America.'},

  {type:'tf',era:'Second Awakening',q:'Charles Finney taught that conversion was God\'s sovereign act and could not be produced by human means.',answer:false,explain:'Finney taught the opposite — that revival was not a miracle but the predictable result of using the right means, and that sinners had the natural ability to choose God at any moment. This was the very thing Hodge charged as Pelagianism.'},

  {type:'mc',era:'Second Awakening',q:'Charles Hodge of Princeton charged that Finney\'s teaching on human ability amounted to which ancient heresy?',correct:'Pelagianism',wrong:['Arianism','Sabellianism','Donatism'],explain:'Hodge accused Finney of reviving Pelagianism — the ancient teaching (condemned in 418) that human beings could save themselves apart from divine grace.'},

  {type:'mc',era:'Second Awakening',q:'The high-church Reformed alternative to Finney\'s revivalism, developed by John Williamson Nevin and Philip Schaff, became known as —',correct:'The Mercersburg Theology',wrong:['The Princeton Theology','The Andover Theology','The New Haven Theology'],explain:'At a small German Reformed seminary in Pennsylvania, Nevin and Schaff developed a high-church Reformed vision emphasizing the Incarnation, real presence in the Eucharist, and the church as a living historical organism.'},

  {type:'mc',era:'Second Awakening',q:'The "Great Disappointment" of 1844 followed the failed prediction of Christ\'s return by which Baptist lay preacher?',correct:'William Miller',wrong:['Joseph Smith','John Nelson Darby','Ellen G. White'],explain:'Miller calculated from Daniel and Revelation that Christ would return in 1844. When the date passed, his following of up to 100,000 was devastated — but some founded Seventh-day Adventism from the wreckage.'},

  {type:'mc',era:'Slavery & Civil War',q:'The Southern Baptist Convention was founded in 1845 specifically because —',correct:'Southern missionary boards rejected a slaveholding candidate for appointment',wrong:['Northern Baptists adopted infant baptism','Northern Baptists abolished the office of deacon','Northern Baptists embraced the Social Gospel'],explain:'The Baptist split of 1845 — like the Methodist split the year before — turned directly on slavery. The two largest American denominations divided over the issue more than a decade before the nation itself did.'},

  {type:'mc',era:'Slavery & Civil War',q:'Why did Richard Allen found the African Methodist Episcopal Church in Philadelphia in 1816?',correct:'After Black worshipers were pulled from their knees during prayer at a white Methodist church',wrong:['After the Methodist Episcopal Church refused to ordain Black bishops','After being expelled for preaching against slavery from a white pulpit','After a court ruling barred Black Christians from white-led congregations'],explain:'Allen, a formerly enslaved man, founded the AME after Black worshipers were pulled from their knees mid-prayer. The AME became the first major institution owned and governed entirely by Black Americans — and the organizational bedrock of Black Christian life.'},

  {type:'quote',era:'Slavery & Civil War',quote:'"Both read the same Bible and pray to the same God, and each invokes His aid against the other."',cite:'— Abraham Lincoln, Second Inaugural Address, 1865',q:'What was Lincoln\'s theological argument in this passage?',correct:'He refused to claim God straightforwardly for the Union, suggesting instead that the war was God\'s judgment on a nation for the sin of slavery',wrong:['He argued that the Confederacy had read the Bible incorrectly and the Union had read it rightly','He claimed that the war proved religion ought to be excluded from public life','He insisted that both sides were equally innocent and that the war was purely political'],explain:'Lincoln\'s Second Inaugural has been called the greatest American theological statement ever made by a political figure — refusing tribal claims on God and reading the war as judgment on the whole nation for slavery.'},

  {type:'mc',era:'Gilded Age',q:'Dwight L. Moody\'s musical partner, whose popular gospel songs transformed revivalist worship in the urban crusade, was —',correct:'Ira Sankey',wrong:['Fanny Crosby','Philip Bliss','Charles Alexander'],explain:'Sankey\'s singing and gospel songs became inseparable from Moody\'s urban crusade format, which combined large halls, choirs, popular music, and organized local-church follow-up.'},

  {type:'mc',era:'Social Gospel',q:'Walter Rauschenbusch\'s 1907 Christianity and the Social Crisis introduced what key term for sin embedded in unjust institutions?',correct:'"Social sin"',wrong:['"Structural evil"','"Public iniquity"','"Industrial sin"'],explain:'After eleven years in New York\'s Hell\'s Kitchen, Rauschenbusch argued that the church had focused too narrowly on individual salvation and neglected the "social sin" embedded in unjust institutions.'},

  {type:'quote',era:'Pentecostalism',quote:'"The color line was washed away in the blood."',cite:'— Frank Bartleman, eyewitness at Azusa Street, 1906',q:'What feature of the Azusa Street revival was Bartleman describing?',correct:'Its interracial worship — Black, white, and Hispanic worshipers gathered together in an era of rigid segregation',wrong:['The healings of wounded Civil War veterans who attended the meetings','A liturgical use of communion in which the cup was passed across racial lines','The deaths of several worshipers in a stampede that the leaders interpreted as martyrdom'],explain:'Led by the Black preacher William J. Seymour in a Los Angeles stable, Azusa drew Black, white, and Hispanic worshipers together — a social miracle in 1906 America and the launching point of global Pentecostalism.'},

  {type:'mc',era:'Fundamentalism',q:'The Fundamentals (1910–1915), the ninety essays defining the conservative movement, were funded by —',correct:'Two California oilmen, Lyman and Milton Stewart',wrong:['The Niagara Bible Conference','Princeton Theological Seminary','The Federal Council of Churches'],explain:'The Stewart brothers underwrote the publication and free distribution of The Fundamentals to every pastor, missionary, and theology student in America — the conservative countermovement\'s opening salvo.'},

  {type:'quote',era:'Fundamentalism',quote:'"In the sphere of religion…liberalism is not a religion within Christianity at all, but a different religion altogether."',cite:'— J. Gresham Machen, Christianity and Liberalism, 1923',q:'What was Machen\'s central argument in this 1923 book?',correct:'That liberal theology had abandoned the historic gospel of redemption and replaced it with a gospel of moral improvement — making it a separate religion, not a revised Christianity',wrong:['That liberalism was a mild error within Christianity that could be corrected by better preaching','That fundamentalism and liberalism were equally legitimate expressions of Christian faith','That liberal theology was identical to Roman Catholicism in its sacramental view'],explain:'Machen, Princeton\'s most rigorous conservative, argued that the difference between liberalism and historic Christianity was not a matter of degree but of kind — they were two different religions sharing borrowed vocabulary.'},

  {type:'mc',era:'Neo-Orthodoxy',q:'Reinhold Niebuhr\'s Moral Man and Immoral Society (1932) argued that —',correct:'Individuals could act morally, but groups (nations, classes, races) inevitably served their own interests and could not be reformed by idealism alone',wrong:['Christian individuals were inevitably corrupted by political engagement and should withdraw from public life','All human moral judgments were ultimately relative to one\'s culture and class','True Christianity required nonviolent pacifism in every situation, public or private'],explain:'Drawing on the doctrine of original sin, Niebuhr argued that power had to be checked by power — a "Christian Realism" that shaped American foreign policy and the labor movement.'},

  {type:'mc',era:'Civil Rights',q:'Martin Luther King Jr.\'s theology of nonviolent resistance drew on which combination of sources?',correct:'The Black church\'s prophetic preaching tradition, the Social Gospel, Gandhi\'s nonviolence, and Niebuhr\'s Christian Realism',wrong:['Pure Black church preaching, with no significant influence from non-American or non-Christian sources','Roman Catholic just-war theory and the pacifism of the historic peace churches','Liberation theology imported from Latin America during the 1960s'],explain:'King, a Baptist pastor with a doctorate in systematic theology, synthesized the Black church\'s prophetic tradition with the Social Gospel, Gandhi, and Niebuhr to articulate a theology of redemptive suffering.'},

  {type:'timeline',era:'20th Century',q:'Place these twentieth-century milestones in chronological order.',events:[
    {label:'The Scopes Trial in Dayton, Tennessee',year:1925},
    {label:'National Association of Evangelicals founded',year:1942},
    {label:'Billy Graham\'s breakout Los Angeles crusade',year:1949},
    {label:'Southern Christian Leadership Conference founded',year:1957},
    {label:'Jerry Falwell Sr. founds the Moral Majority',year:1979},
  ],explain:'These five events trace the arc of twentieth-century American Christianity: fundamentalist humiliation and withdrawal, neo-evangelical re-engagement, the Black church\'s civil-rights leadership, and the Religious Right\'s return to politics.'},
]}

